struct DaemonProcess {
    child: Child,
    log_path: PathBuf,
}

impl DaemonProcess {
    fn logs(&self) -> String {
        fs::read_to_string(&self.log_path).unwrap_or_default()
    }
}

impl Drop for DaemonProcess {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

fn stop_daemon(daemon: &mut DaemonProcess) -> Result<()> {
    if daemon.child.try_wait()?.is_some() {
        return Ok(());
    }
    daemon
        .child
        .kill()
        .context("failed to stop daemon process")?;
    daemon
        .child
        .wait()
        .context("failed to reap daemon process")?;
    Ok(())
}

#[cfg(unix)]
fn terminate_daemon(daemon: &mut DaemonProcess) -> Result<()> {
    if daemon.child.try_wait()?.is_some() {
        return Ok(());
    }
    let pid = daemon.child.id() as i32;
    let status = unsafe { libc::kill(pid, libc::SIGTERM) };
    if status != 0 {
        return Err(std::io::Error::last_os_error()).context("failed to send SIGTERM to daemon");
    }
    Ok(())
}

fn cli_bin() -> Result<PathBuf> {
    if let Some(path) = std::env::var_os("CARGO_BIN_EXE_kheish-daemon") {
        return Ok(PathBuf::from(path));
    }
    let fallback =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../target/debug/kheish-daemon");
    if fallback.exists() {
        return Ok(fallback);
    }
    Err(anyhow!(
        "failed to locate kheish-daemon binary via CARGO_BIN_EXE_kheish-daemon or target/debug"
    ))
}

fn python_connector_script() -> Result<PathBuf> {
    let path =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../connectors/python/run_connector.py");
    if path.exists() {
        return Ok(path);
    }
    Err(anyhow!(
        "failed to locate external connector launcher at {}",
        path.display()
    ))
}

fn reserve_bind_address() -> Result<String> {
    let listener = std::net::TcpListener::bind("127.0.0.1:0")?;
    let address = listener.local_addr()?;
    Ok(address.to_string())
}

fn start_daemon_with_env_and_args<I, K, V>(
    bin: &Path,
    temp: &TempDir,
    bind: &str,
    state_root: &Path,
    workspace_root: &Path,
    routes_path: &Path,
    default_route: Option<&str>,
    extra_args: &[OsString],
    envs: I,
) -> Result<DaemonProcess>
where
    I: IntoIterator<Item = (K, V)>,
    K: AsRef<std::ffi::OsStr>,
    V: AsRef<std::ffi::OsStr>,
{
    let log_path = temp.path().join("daemon.log");
    let log_file = File::create(&log_path)?;
    let stderr_file = log_file.try_clone()?;
    let mut command = Command::new(bin);
    command.args([
        OsString::from("serve"),
        OsString::from("--bind"),
        OsString::from(bind),
        OsString::from("--state-root"),
        state_root.as_os_str().to_os_string(),
        OsString::from("--workspace-root"),
        workspace_root.as_os_str().to_os_string(),
        OsString::from("--routes-file"),
        routes_path.as_os_str().to_os_string(),
    ]);
    command.args(extra_args);
    if let Some(default_route) = default_route {
        command.arg("--default-route").arg(default_route);
    }
    for name in [
        AUTH_STORE_MASTER_KEY_ENV,
        AUTH_STORE_MASTER_KEY_FILE_ENV,
        "KHEISH_MCP_CONFIG",
        "KHEISH_MCP_CREDENTIALS",
        "KHEISH_MCP_DISCOVERY",
    ] {
        command.env_remove(name);
    }
    for (name, value) in envs {
        command.env(name, value);
    }
    let child = command
        .stdout(Stdio::from(log_file))
        .stderr(Stdio::from(stderr_file))
        .spawn()
        .context("failed to start daemon process")?;
    Ok(DaemonProcess { child, log_path })
}

