fn run_cli_json<T, I, S>(bin: &Path, base_url: &str, args: I) -> Result<T>
where
    T: DeserializeOwned,
    I: IntoIterator<Item = S>,
    S: Into<OsString>,
{
    run_cli_json_with_env(bin, base_url, args, std::iter::empty::<(&str, &str)>())
}

fn run_cli_json_with_env<T, I, S, E, K, V>(
    bin: &Path,
    base_url: &str,
    args: I,
    envs: E,
) -> Result<T>
where
    T: DeserializeOwned,
    I: IntoIterator<Item = S>,
    S: Into<OsString>,
    E: IntoIterator<Item = (K, V)>,
    K: AsRef<std::ffi::OsStr>,
    V: AsRef<std::ffi::OsStr>,
{
    let mut command = Command::new(bin);
    command
        .arg("--base-url")
        .arg(base_url)
        .arg("--output")
        .arg("json");
    for arg in args {
        command.arg(arg.into());
    }
    for (name, value) in envs {
        command.env(name, value);
    }
    let output = command.output().context("failed to run CLI command")?;
    if !output.status.success() {
        bail!(
            "CLI command failed with status {}\nstdout:\n{}\nstderr:\n{}",
            output.status,
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
    }
    serde_json::from_slice(&output.stdout).context("failed to decode CLI JSON output")
}

fn run_cli_json_with_stdin<T, I, S>(bin: &Path, base_url: &str, args: I, stdin: &str) -> Result<T>
where
    T: DeserializeOwned,
    I: IntoIterator<Item = S>,
    S: Into<OsString>,
{
    let mut command = Command::new(bin);
    command
        .arg("--base-url")
        .arg(base_url)
        .arg("--output")
        .arg("json")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    for arg in args {
        command.arg(arg.into());
    }
    let mut child = command.spawn().context("failed to run CLI command")?;
    child
        .stdin
        .as_mut()
        .context("CLI stdin was not piped")?
        .write_all(stdin.as_bytes())
        .context("failed to write CLI stdin")?;
    let output = child
        .wait_with_output()
        .context("failed to wait for CLI command")?;
    if !output.status.success() {
        bail!(
            "CLI command failed with status {}\nstdout:\n{}\nstderr:\n{}",
            output.status,
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
    }
    serde_json::from_slice(&output.stdout).context("failed to decode CLI JSON output")
}

fn run_cli_output_with_stdin<I, S>(
    bin: &Path,
    base_url: &str,
    args: I,
    stdin: &str,
) -> Result<std::process::Output>
where
    I: IntoIterator<Item = S>,
    S: Into<OsString>,
{
    let mut command = Command::new(bin);
    command
        .arg("--base-url")
        .arg(base_url)
        .arg("--output")
        .arg("json")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    for arg in args {
        command.arg(arg.into());
    }
    let mut child = command.spawn().context("failed to run CLI command")?;
    child
        .stdin
        .as_mut()
        .context("CLI stdin was not piped")?
        .write_all(stdin.as_bytes())
        .context("failed to write CLI stdin")?;
    child
        .wait_with_output()
        .context("failed to wait for CLI command")
}

fn run_cli_output<I, S>(bin: &Path, base_url: &str, args: I) -> Result<std::process::Output>
where
    I: IntoIterator<Item = S>,
    S: Into<OsString>,
{
    run_cli_output_with_env(bin, base_url, args, std::iter::empty::<(&str, &str)>())
}

fn assert_run_debug_artifacts_do_not_contain(
    bin: &Path,
    base_url: &str,
    run_id: &str,
    forbidden: &[&str],
) -> Result<()> {
    let debug_view: RunDebugView = run_cli_json(bin, base_url, ["runs", "debug", run_id])?;
    assert_eq!(debug_view.level, DebugCaptureLevel::Full);
    assert!(
        !debug_view.artifacts.is_empty(),
        "debug artifacts should be captured for run {run_id}"
    );
    for artifact in debug_view.artifacts {
        let output = run_cli_output(
            bin,
            base_url,
            [
                "runs",
                "debug-artifact",
                run_id,
                artifact.artifact_id.as_str(),
            ],
        )?;
        assert!(
            output.status.success(),
            "runs debug-artifact failed for {}\nstdout:\n{}\nstderr:\n{}",
            artifact.artifact_id,
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        let artifact_text = String::from_utf8_lossy(&output.stdout);
        for secret in forbidden {
            assert!(
                !artifact_text.contains(secret),
                "debug artifact {} leaked forbidden secret {secret}",
                artifact.artifact_id
            );
        }
    }
    Ok(())
}

fn assert_tree_files_do_not_contain(root: &Path, forbidden: &[&str]) -> Result<()> {
    let mut stack = vec![root.to_path_buf()];
    while let Some(path) = stack.pop() {
        let metadata = fs::symlink_metadata(&path)
            .with_context(|| format!("failed to stat {}", path.display()))?;
        if metadata.file_type().is_symlink() {
            continue;
        }
        if metadata.is_dir() {
            for entry in fs::read_dir(&path)
                .with_context(|| format!("failed to read directory {}", path.display()))?
            {
                stack.push(entry?.path());
            }
            continue;
        }
        if !metadata.is_file() {
            continue;
        }
        let bytes =
            fs::read(&path).with_context(|| format!("failed to read {}", path.display()))?;
        let text = String::from_utf8_lossy(&bytes);
        for secret in forbidden {
            assert!(
                !text.contains(secret),
                "state file {} leaked forbidden secret {secret}",
                path.display()
            );
        }
    }
    Ok(())
}

fn run_cli_json_expect_failure<T, I, S>(bin: &Path, base_url: &str, args: I) -> Result<T>
where
    T: DeserializeOwned,
    I: IntoIterator<Item = S>,
    S: Into<OsString>,
{
    let output = run_cli_output(bin, base_url, args)?;
    if output.status.success() {
        bail!(
            "CLI command unexpectedly succeeded\nstdout:\n{}\nstderr:\n{}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
    }
    serde_json::from_slice(&output.stdout).context("failed to decode failed CLI JSON output")
}

