async fn run_cli_stream_until_contains<I, S>(
    bin: &Path,
    base_url: &str,
    args: I,
    needle: &str,
) -> Result<String>
where
    I: IntoIterator<Item = S>,
    S: Into<OsString>,
{
    let mut command = TokioCommand::new(bin);
    command
        .arg("--base-url")
        .arg(base_url)
        .arg("--output")
        .arg("json")
        .stdout(Stdio::piped())
        .stderr(Stdio::null());
    for arg in args {
        command.arg(arg.into());
    }

    let mut child = command
        .spawn()
        .context("failed to spawn CLI stream command")?;
    let mut stdout = child
        .stdout
        .take()
        .ok_or_else(|| anyhow!("streaming CLI command did not expose stdout"))?;
    let mut captured = Vec::new();
    let found = tokio::time::timeout(Duration::from_secs(10), async {
        let mut buffer = [0_u8; 1024];
        loop {
            let read = stdout
                .read(&mut buffer)
                .await
                .context("failed to read CLI stream stdout")?;
            if read == 0 {
                return Ok::<bool, anyhow::Error>(false);
            }
            captured.extend_from_slice(&buffer[..read]);
            if String::from_utf8_lossy(&captured).contains(needle) {
                return Ok::<bool, anyhow::Error>(true);
            }
        }
    })
    .await
    .context("timed out waiting for CLI stream output")??;

    if child.try_wait()?.is_none() {
        let _ = child.kill().await;
    }
    let _ = child.wait().await;

    let output = String::from_utf8_lossy(&captured).into_owned();
    anyhow::ensure!(
        found,
        "CLI stream ended before output contained {needle:?}\nstdout:\n{output}"
    );
    Ok(output)
}

async fn next_sse_json_event(
    response: &mut reqwest::Response,
) -> Result<(Option<u64>, String, Value)> {
    let mut buffer = String::new();
    loop {
        for delimiter in ["\r\n\r\n", "\n\n"] {
            if let Some(frame_end) = buffer.find(delimiter) {
                let frame = buffer[..frame_end].to_string();
                buffer.replace_range(..frame_end + delimiter.len(), "");
                let mut id = None;
                let mut event_name = None;
                let mut data_lines = Vec::new();
                for line in frame.lines() {
                    let line = line.trim_end_matches('\r');
                    if line.is_empty() || line.starts_with(':') {
                        continue;
                    }
                    if let Some(value) = line.strip_prefix("id:") {
                        let value = value.trim();
                        if !value.is_empty() {
                            id = Some(value.parse::<u64>()?);
                        }
                    } else if let Some(value) = line.strip_prefix("event:") {
                        event_name = Some(value.trim().to_string());
                    } else if let Some(value) = line.strip_prefix("data:") {
                        data_lines.push(value.trim_start().to_string());
                    }
                }
                if let Some(event_name) = event_name {
                    let data = serde_json::from_str::<Value>(&data_lines.join("\n"))?;
                    return Ok((id, event_name, data));
                }
            }
        }

        let chunk = tokio::time::timeout(Duration::from_secs(15), response.chunk())
            .await
            .context("timed out waiting for SSE event")??
            .ok_or_else(|| anyhow!("SSE stream ended before an event arrived"))?;
        buffer.push_str(std::str::from_utf8(&chunk).context("SSE chunk was not UTF-8")?);
    }
}

fn wait_for_daemon_ready(bin: &Path, base_url: &str, daemon: &DaemonProcess) -> Result<()> {
    wait_for_daemon_ready_with_env(bin, base_url, daemon, std::iter::empty::<(&str, &str)>())
}

fn wait_for_daemon_ready_with_env<E, K, V>(
    bin: &Path,
    base_url: &str,
    daemon: &DaemonProcess,
    envs: E,
) -> Result<()>
where
    E: Clone + IntoIterator<Item = (K, V)>,
    K: AsRef<std::ffi::OsStr>,
    V: AsRef<std::ffi::OsStr>,
{
    let deadline = Instant::now() + Duration::from_secs(20);
    loop {
        match run_cli_json_with_env::<RuntimeSettingsView, _, _, _, _, _>(
            bin,
            base_url,
            ["runtime", "get"],
            envs.clone(),
        ) {
            Ok(_) => return Ok(()),
            Err(error) if Instant::now() < deadline => {
                std::thread::sleep(Duration::from_millis(150));
                let _ = error;
            }
            Err(error) => {
                bail!(
                    "daemon did not become ready: {error}\ndaemon logs:\n{}",
                    daemon.logs()
                );
            }
        }
    }
}

fn start_daemon_ready(
    bin: &Path,
    temp: &TempDir,
    state_root: &Path,
    workspace_root: &Path,
    routes_path: &Path,
) -> Result<(String, DaemonProcess)> {
    start_daemon_ready_with_env(
        bin,
        temp,
        state_root,
        workspace_root,
        routes_path,
        Some("openrouter"),
        std::iter::empty::<(&str, &str)>(),
    )
}

