async fn start_openai_mock_route_daemon(
    bin: &Path,
    temp: &TempDir,
    state_root: &Path,
    workspace_root: &Path,
    text_responses: Vec<String>,
) -> Result<(String, DaemonProcess)> {
    let provider_base_url = spawn_openai_route_mock_server(
        text_responses,
        Vec::new(),
        Vec::new(),
        Arc::new(Mutex::new(Vec::new())),
    )
    .await?;
    let routes_path = temp.path().join("routes.toml");
    write_routes_file(&routes_path, &provider_base_url, &provider_base_url)?;
    start_daemon_ready(bin, temp, state_root, workspace_root, &routes_path)
}

async fn assert_problem_response(
    response: reqwest::Response,
    status: StatusCode,
    code: &str,
) -> Result<ProblemDetails> {
    assert_eq!(response.status(), status);
    let content_type = response
        .headers()
        .get(header::CONTENT_TYPE)
        .context("problem response content-type missing")?
        .to_str()?
        .to_string();
    assert!(
        content_type.starts_with("application/problem+json"),
        "unexpected content-type {content_type}"
    );
    let problem = response.json::<ProblemDetails>().await?;
    assert_eq!(problem.status, status.as_u16());
    assert_eq!(problem.code, code);
    Ok(problem)
}

