fn visible_agent_display_name(session: &SessionView) -> String {
    session
        .snapshot
        .agent
        .nickname
        .clone()
        .or(session.snapshot.agent.name.clone())
        .unwrap_or_else(|| session.snapshot.agent.id.0.clone())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn daemon_control_plane_problem_details_and_openapi_contract() -> Result<()> {
    let bin = cli_bin()?;
    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let (base_url, _daemon) =
        start_openai_mock_route_daemon(&bin, &temp, &state_root, &workspace_root, Vec::new())
            .await?;
    let client = Client::new();

    let missing = client
        .get(format!("{base_url}/v1/sessions/missing-session"))
        .send()
        .await?;
    let missing_problem =
        assert_problem_response(missing, StatusCode::NOT_FOUND, "session_not_found").await?;
    assert_eq!(missing_problem.domain.as_deref(), Some("sessions"));
    assert!(missing_problem.detail.contains("unknown session"));

    let unknown_route = client
        .get(format!("{base_url}/v1/does-not-exist"))
        .send()
        .await?;
    let unknown_route_problem =
        assert_problem_response(unknown_route, StatusCode::NOT_FOUND, "route_not_found").await?;
    assert_eq!(unknown_route_problem.domain.as_deref(), Some("api"));

    for path in ["/healthz", "/readyz", "/v1/status"] {
        let wrong_method = client.post(format!("{base_url}{path}")).send().await?;
        let allow_header = wrong_method
            .headers()
            .get(header::ALLOW)
            .context("method-not-allowed response should preserve Allow header")?
            .to_str()?
            .to_string();
        assert!(
            allow_header.contains("GET"),
            "{path} 405 should preserve Allow: GET, got {allow_header}"
        );
        let problem = assert_problem_response(
            wrong_method,
            StatusCode::METHOD_NOT_ALLOWED,
            "method_not_allowed",
        )
        .await?;
        assert_eq!(
            problem.status,
            StatusCode::METHOD_NOT_ALLOWED.as_u16(),
            "{path} should preserve the HTTP status in its problem body"
        );
    }

    let unknown_connector_ingress = client
        .post(format!("{base_url}/v1/connectors/http/missing"))
        .header(header::CONTENT_TYPE, "application/json")
        .body("{}")
        .send()
        .await?;
    let unknown_connector_problem = assert_problem_response(
        unknown_connector_ingress,
        StatusCode::NOT_FOUND,
        "not_found",
    )
    .await?;
    assert_eq!(
        unknown_connector_problem.domain.as_deref(),
        Some("connector_ingress")
    );

    let invalid_connector_json = client
        .post(format!("{base_url}/v1/connectors/telegram/missing"))
        .header(header::CONTENT_TYPE, "application/json")
        .body("{")
        .send()
        .await?;
    let invalid_connector_problem = assert_problem_response(
        invalid_connector_json,
        StatusCode::BAD_REQUEST,
        "bad_request",
    )
    .await?;
    assert_eq!(
        invalid_connector_problem.domain.as_deref(),
        Some("connector_ingress")
    );

    let invalid_json = client
        .post(format!("{base_url}/v1/sessions"))
        .header(header::CONTENT_TYPE, "application/json")
        .body("{")
        .send()
        .await?;
    assert_problem_response(invalid_json, StatusCode::BAD_REQUEST, "bad_request").await?;

    let capabilities: kheish_daemon::DaemonCapabilities = client
        .get(format!("{base_url}/v1/capabilities"))
        .send()
        .await?
        .json()
        .await?;
    assert!(capabilities.problem_details);
    assert!(capabilities.openapi);
    assert!(capabilities.cursor_pagination);
    assert!(capabilities.domain_errors);
    assert!(capabilities.sse_replay);
    assert!(capabilities.typed_sse_heartbeat);
    assert!(capabilities.api_revision >= 3);

    let openapi_response = client
        .get(format!("{base_url}/v1/openapi.json"))
        .send()
        .await?;
    let openapi_content_type = openapi_response
        .headers()
        .get(header::CONTENT_TYPE)
        .context("OpenAPI content-type missing")?
        .to_str()?;
    assert!(
        openapi_content_type.starts_with("application/json"),
        "OpenAPI should be served as JSON, got {openapi_content_type}"
    );
    let openapi: Value = openapi_response.json().await?;
    assert_eq!(openapi["openapi"], "3.1.0");
    assert!(openapi["paths"]["/v1/status"]["get"].is_object());
    assert!(openapi["paths"]["/v1/events/stream"]["get"].is_object());
    assert!(openapi["paths"]["/v1/sessions/{session_id}"]["get"].is_object());
    assert!(openapi["paths"]["/v1/runs/{run_id}"]["get"].is_object());
    assert!(openapi["paths"]["/v1/observation-sources"]["get"].is_object());
    assert!(openapi["paths"]["/healthz"]["get"].is_object());
    assert!(openapi["paths"]["/readyz"]["get"].is_object());
    assert!(openapi["paths"]["/v1/connectors/http/{name}"]["post"].is_object());
    assert!(openapi["paths"]["/v1/connectors/external/{name}/events/batch"]["post"].is_object());
    assert_eq!(
        openapi["paths"]["/v1/connectors/http/{name}"]["post"]["security"],
        json!([
            { "connectorBearer": [] },
            { "httpConnectorHmac": [], "httpConnectorTimestamp": [] }
        ])
    );
    assert_eq!(
        openapi["paths"]["/v1/connectors/slack/{name}"]["post"]["security"],
        json!([{ "slackSignature": [], "slackRequestTimestamp": [] }])
    );
    assert_eq!(
        openapi["paths"]["/v1/observation-sources/{source_id}/observations"]["post"]["security"],
        json!([{ "observationUploadToken": [] }])
    );
    assert_eq!(
        openapi["paths"]["/v1/capture-agents/{machine_id}/heartbeat"]["post"]["security"],
        json!([{ "captureAgentToken": [] }])
    );
    assert!(openapi["paths"]["/v1/deliveries/{delivery_id}/resolve"]["post"].is_object());
    assert_eq!(
        openapi["components"]["schemas"]["ProblemDetails"]["properties"]["domain"]["type"],
        "string"
    );
    assert_eq!(
        openapi["paths"]["/v1/sessions/{session_id}"]["get"]["parameters"][0]["name"],
        "session_id"
    );
    assert!(
        openapi["paths"]["/v1/runs"]["get"]["parameters"]
            .as_array()
            .expect("run list parameters")
            .iter()
            .any(|parameter| parameter["name"] == "priority_active")
    );
    assert_eq!(
        openapi["components"]["responses"]["Problem"]["content"]["application/problem+json"]["schema"]
            ["$ref"],
        "#/components/schemas/ProblemDetails"
    );
    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn cli_problem_details_use_stable_exit_code_matrix() -> Result<()> {
    let bin = cli_bin()?;
    let listener = TcpListener::bind("127.0.0.1:0").await?;
    let base_url = format!("http://{}", listener.local_addr()?);
    let router = Router::new().route(
        "/v1/sessions/{session_id}",
        get(|AxumPath(session_id): AxumPath<String>| async move {
            let (status, domain, code, detail) = match session_id.as_str() {
                "bad" => (
                    StatusCode::BAD_REQUEST,
                    "sessions",
                    "bad_request",
                    "bad session id",
                ),
                "unauth" => (
                    StatusCode::UNAUTHORIZED,
                    "auth",
                    "missing_token",
                    "missing daemon token",
                ),
                "forbidden" => (
                    StatusCode::FORBIDDEN,
                    "auth",
                    "insufficient_access",
                    "daemon token does not allow this operation",
                ),
                "conflict" => (
                    StatusCode::CONFLICT,
                    "sessions",
                    "session_not_idle",
                    "session is not idle",
                ),
                "large" => (
                    StatusCode::PAYLOAD_TOO_LARGE,
                    "http",
                    "payload_too_large",
                    "payload is too large",
                ),
                "method" => (
                    StatusCode::METHOD_NOT_ALLOWED,
                    "api",
                    "method_not_allowed",
                    "wrong method",
                ),
                "rate" => (
                    StatusCode::TOO_MANY_REQUESTS,
                    "auth",
                    "rate_limited",
                    "too many auth failures",
                ),
                "server" => (
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "api",
                    "internal_error",
                    "server failed",
                ),
                _ => (
                    StatusCode::NOT_FOUND,
                    "sessions",
                    "session_not_found",
                    "unknown session missing-session",
                ),
            };
            (
                status,
                [(header::CONTENT_TYPE, "application/problem+json")],
                Json(ProblemDetails::new(status.as_u16(), code, detail).with_domain(domain)),
            )
        }),
    );
    tokio::spawn(async move {
        axum::serve(listener, router)
            .await
            .expect("fake CLI server");
    });

    for (session_id, expected_exit, expected_code) in [
        ("bad", 2, "bad_request"),
        ("unauth", 4, "missing_token"),
        ("forbidden", 4, "insufficient_access"),
        ("missing-session", 5, "session_not_found"),
        ("conflict", 6, "session_not_idle"),
        ("large", 2, "payload_too_large"),
        ("method", 1, "method_not_allowed"),
        ("rate", 7, "rate_limited"),
        ("server", 1, "internal_error"),
    ] {
        let output = run_cli_output(&bin, &base_url, ["sessions", "get", session_id])?;
        assert_eq!(
            output.status.code(),
            Some(expected_exit),
            "unexpected exit for {session_id}\nstderr:\n{}",
            String::from_utf8_lossy(&output.stderr)
        );
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(
            stderr.contains(expected_code),
            "stderr for {session_id} did not contain {expected_code}\n{stderr}"
        );
    }
    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn paginated_cli_accepts_legacy_array_from_old_daemon() -> Result<()> {
    let bin = cli_bin()?;
    let listener = TcpListener::bind("127.0.0.1:0").await?;
    let base_url = format!("http://{}", listener.local_addr()?);
    let router = Router::new()
        .route(
            "/v1/sessions",
            get(|| async {
                Json(json!([
                    {
                        "session_id": "legacy-a",
                        "agent_id": "agent-legacy-a",
                        "status": "idle",
                        "pending_approvals": 0
                    },
                    {
                        "session_id": "legacy-b",
                        "agent_id": "agent-legacy-b",
                        "status": "idle",
                        "pending_approvals": 0
                    }
                ]))
            }),
        )
        .route(
            "/v1/agents/summaries",
            get(|| async {
                Json(json!([
                    {
                        "agent_id": "agent-legacy-a",
                        "session_id": "legacy-a",
                        "status": "idle",
                        "retention": "retain",
                        "spawned_at_ms": 1,
                        "subtask_count": 0,
                        "mailbox_message_count": 0,
                        "has_runtime": false
                    },
                    {
                        "agent_id": "agent-legacy-b",
                        "session_id": "legacy-b",
                        "status": "running",
                        "retention": "retain",
                        "spawned_at_ms": 2,
                        "subtask_count": 0,
                        "mailbox_message_count": 0,
                        "has_runtime": true
                    }
                ]))
            }),
        );
    tokio::spawn(async move {
        axum::serve(listener, router)
            .await
            .expect("fake legacy daemon server");
    });

    let page: kheish_daemon::ListPage<SessionViewSummary> = run_cli_json(
        &bin,
        &base_url,
        ["sessions", "list", "--page", "--limit", "1"],
    )?;
    assert_eq!(page.items.len(), 2);
    assert_eq!(page.pagination.total_count, 2);
    assert_eq!(page.pagination.order, "legacy_array");
    assert!(!page.pagination.has_more);

    let page: kheish_daemon::AgentSummaryListPage = run_cli_json(
        &bin,
        &base_url,
        ["agents", "summaries", "--page", "--limit", "1"],
    )?;
    assert_eq!(page.items.len(), 2);
    assert_eq!(page.pagination.total_count, 2);
    assert_eq!(page.pagination.order, "legacy_array");
    assert_eq!(page.counts.filtered, 2);
    assert_eq!(page.counts.idle, 1);
    assert_eq!(page.counts.running, 1);
    assert_eq!(page.counts.with_runtime, 1);
    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn cli_encodes_reserved_session_path_segments() -> Result<()> {
    let bin = cli_bin()?;
    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let (base_url, _daemon) =
        start_openai_mock_route_daemon(&bin, &temp, &state_root, &workspace_root, Vec::new())
            .await?;

    for reserved_session_id in [".", ".."] {
        let output = run_cli_output(&bin, &base_url, ["sessions", "create", reserved_session_id])?;
        assert_eq!(output.status.code(), Some(2));
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(
            stderr.contains("invalid_session_id"),
            "reserved session id {reserved_session_id:?} should return typed invalid_session_id: {stderr}"
        );

        let response = Client::new()
            .post(format!("{base_url}/v1/sessions"))
            .json(&json!({"session_id": reserved_session_id}))
            .send()
            .await?;
        let problem =
            assert_problem_response(response, StatusCode::BAD_REQUEST, "invalid_session_id")
                .await?;
        assert_eq!(problem.domain.as_deref(), Some("sessions"));
    }

    for session_id in [
        "a/b",
        "space id",
        "query?x=1",
        "fragment#part",
        "percent%2Fencoded",
        "dot..segment",
        "windows\\path",
    ] {
        let session: SessionView =
            run_cli_json(&bin, &base_url, ["sessions", "create", session_id])?;
        assert_eq!(session.session_id, session_id);

        let fetched: SessionView = run_cli_json(&bin, &base_url, ["sessions", "get", session_id])?;
        assert_eq!(fetched.session_id, session_id);

        let encoded = urlencoding::encode(session_id);
        let fetched_http: SessionView = Client::new()
            .get(format!("{base_url}/v1/sessions/{encoded}"))
            .send()
            .await?
            .error_for_status()?
            .json()
            .await?;
        assert_eq!(fetched_http.session_id, session_id);
    }
    Ok(())
}

