#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn control_plane_pagination_contract_real_daemon() -> Result<()> {
    let bin = cli_bin()?;
    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let (base_url, _daemon) =
        start_openai_mock_route_daemon(&bin, &temp, &state_root, &workspace_root, Vec::new())
            .await?;
    let client = Client::new();

    for session_id in ["page-a", "page-b", "page-c"] {
        let session: SessionView =
            run_cli_json(&bin, &base_url, ["sessions", "create", session_id])?;
        assert_eq!(session.session_id, session_id);
    }

    let legacy: Value = client
        .get(format!("{base_url}/v1/sessions"))
        .send()
        .await?
        .json()
        .await?;
    assert!(legacy.is_array(), "legacy list shape changed: {legacy}");

    let legacy_with_limit: Value = client
        .get(format!("{base_url}/v1/sessions?limit=2"))
        .send()
        .await?
        .json()
        .await?;
    assert!(
        legacy_with_limit.is_array(),
        "limit-only list requests must keep the legacy array shape: {legacy_with_limit}"
    );
    assert_eq!(
        legacy_with_limit
            .as_array()
            .expect("legacy limit-only array")
            .len(),
        2,
        "limit-only list requests should apply the bounded limit while preserving array shape"
    );

    let first_page: kheish_daemon::ListPage<SessionViewSummary> = client
        .get(format!("{base_url}/v1/sessions?page=true&limit=2"))
        .send()
        .await?
        .json()
        .await?;
    let first_ids = first_page
        .items
        .iter()
        .map(|session| session.session_id.as_str())
        .collect::<Vec<_>>();
    assert_eq!(first_ids, vec!["page-a", "page-b"]);
    assert_eq!(first_page.pagination.limit, 2);
    assert!(first_page.pagination.has_more);
    assert_eq!(first_page.pagination.order, "session_id_asc");
    let cursor = first_page
        .pagination
        .next_cursor
        .clone()
        .context("first page should return next cursor")?;

    let second_page: kheish_daemon::ListPage<SessionViewSummary> = client
        .get(format!(
            "{base_url}/v1/sessions?page=true&limit=2&cursor={}",
            urlencoding::encode(&cursor)
        ))
        .send()
        .await?
        .json()
        .await?;
    let second_ids = second_page
        .items
        .iter()
        .map(|session| session.session_id.as_str())
        .collect::<Vec<_>>();
    assert_eq!(second_ids, vec!["page-c"]);
    assert!(!second_page.pagination.has_more);
    assert!(second_page.pagination.next_cursor.is_none());

    let cli_legacy_limited: Vec<SessionViewSummary> =
        run_cli_json(&bin, &base_url, ["sessions", "list", "--limit", "2"])?;
    assert_eq!(
        cli_legacy_limited.len(),
        2,
        "CLI limit-only list should preserve legacy array output"
    );

    let cli_page: kheish_daemon::ListPage<SessionViewSummary> = run_cli_json(
        &bin,
        &base_url,
        ["sessions", "list", "--page", "--limit", "2"],
    )?;
    assert_eq!(cli_page.items.len(), 2);
    assert!(cli_page.pagination.has_more);
    let cli_cursor_page: kheish_daemon::ListPage<SessionViewSummary> = run_cli_json(
        &bin,
        &base_url,
        ["sessions", "list", "--cursor", &cursor, "--limit", "2"],
    )?;
    assert_eq!(cli_cursor_page.items.len(), 1);
    assert_eq!(cli_cursor_page.items[0].session_id, "page-c");
    assert!(!cli_cursor_page.pagination.has_more);

    let agent_summary_page: kheish_daemon::AgentSummaryListPage = client
        .get(format!("{base_url}/v1/agents/summaries?page=true&limit=2"))
        .send()
        .await?
        .json()
        .await?;
    assert_eq!(agent_summary_page.pagination.limit, 2);
    assert_eq!(agent_summary_page.pagination.total_count, 3);
    assert_eq!(agent_summary_page.counts.total, 3);
    assert_eq!(agent_summary_page.counts.filtered, 3);
    assert_eq!(agent_summary_page.counts.idle, 3);
    assert!(agent_summary_page.pagination.has_more);
    let agent_legacy_limit: Value = client
        .get(format!("{base_url}/v1/agents/summaries?limit=1"))
        .send()
        .await?
        .json()
        .await?;
    assert_eq!(
        agent_legacy_limit
            .as_array()
            .expect("agent summaries legacy limit array")
            .len(),
        1,
        "agent summaries limit-only requests should preserve array shape while applying limit"
    );
    let agent_cli_page: kheish_daemon::ListPage<kheish_daemon::AgentSummaryView> = run_cli_json(
        &bin,
        &base_url,
        ["agents", "summaries", "--page", "--limit", "2"],
    )?;
    assert_eq!(agent_cli_page.items.len(), 2);
    assert_eq!(agent_cli_page.pagination.total_count, 3);
    let agent_cli_legacy_limited: Vec<kheish_daemon::AgentSummaryView> =
        run_cli_json(&bin, &base_url, ["agents", "summaries", "--limit", "2"])?;
    assert_eq!(agent_cli_legacy_limited.len(), 2);
    let filtered_agents: Vec<kheish_daemon::AgentSummaryView> = run_cli_json(
        &bin,
        &base_url,
        [
            "agents",
            "summaries",
            "--session-id",
            "page-a",
            "--status",
            "idle",
            "--has-runtime",
            "true",
        ],
    )?;
    assert_eq!(filtered_agents.len(), 1);
    assert_eq!(filtered_agents[0].session_id, "page-a");

    let runs_page: kheish_daemon::ListPage<RunView> = client
        .get(format!("{base_url}/v1/runs?page=true&limit=1"))
        .send()
        .await?
        .json()
        .await?;
    assert_eq!(runs_page.pagination.limit, 1);
    assert_eq!(runs_page.pagination.order, "submitted_at_ms_asc,run_id_asc");

    let assets_page: kheish_daemon::ListPage<kheish_daemon::AssetSummaryView> = client
        .get(format!("{base_url}/v1/assets?page=true&limit=1"))
        .send()
        .await?
        .json()
        .await?;
    assert_eq!(assets_page.pagination.limit, 1);
    assert_eq!(assets_page.pagination.order, "asset_id_asc");

    let personas_page: kheish_daemon::ListPage<kheish_daemon::PersonaSummaryView> = client
        .get(format!("{base_url}/v1/personas?page=true&limit=1"))
        .send()
        .await?
        .json()
        .await?;
    assert_eq!(personas_page.pagination.limit, 1);
    assert_eq!(personas_page.pagination.order, "persona_id_asc");

    let schedules_page: kheish_daemon::ListPage<ScheduleView> = client
        .get(format!("{base_url}/v1/schedules?page=true&limit=1"))
        .send()
        .await?
        .json()
        .await?;
    assert_eq!(schedules_page.pagination.limit, 1);
    assert_eq!(schedules_page.pagination.order, "schedule_id_asc");

    let questions_page: kheish_daemon::ListPage<PendingQuestionView> = client
        .get(format!("{base_url}/v1/questions?page=true&limit=1"))
        .send()
        .await?
        .json()
        .await?;
    assert_eq!(questions_page.pagination.limit, 1);
    assert_eq!(
        questions_page.pagination.order,
        "session_id_asc,request_id_asc"
    );

    let _: kheish_daemon::ListPage<kheish_daemon::AssetSummaryView> = run_cli_json(
        &bin,
        &base_url,
        ["assets", "list", "--page", "--limit", "1"],
    )?;
    let _: kheish_daemon::ListPage<kheish_daemon::PersonaSummaryView> = run_cli_json(
        &bin,
        &base_url,
        ["personas", "list", "--page", "--limit", "1"],
    )?;
    let _: kheish_daemon::ListPage<ScheduleView> = run_cli_json(
        &bin,
        &base_url,
        ["schedules", "list", "--page", "--limit", "1"],
    )?;
    let _: kheish_daemon::ListPage<PendingQuestionView> = run_cli_json(
        &bin,
        &base_url,
        ["questions", "list", "--page", "--limit", "1"],
    )?;
    let _: Vec<RunView> = run_cli_json(&bin, &base_url, ["runs", "list", "--limit", "1"])?;
    let _: Vec<kheish_daemon::AssetSummaryView> =
        run_cli_json(&bin, &base_url, ["assets", "list", "--limit", "1"])?;
    let _: Vec<kheish_daemon::PersonaSummaryView> =
        run_cli_json(&bin, &base_url, ["personas", "list", "--limit", "1"])?;
    let _: Vec<ScheduleView> =
        run_cli_json(&bin, &base_url, ["schedules", "list", "--limit", "1"])?;
    let _: Vec<PendingQuestionView> =
        run_cli_json(&bin, &base_url, ["questions", "list", "--limit", "1"])?;
    let _: Vec<TaskRecord> =
        run_cli_json(&bin, &base_url, ["tasks", "list", "page-a", "--limit", "1"])?;
    let _: Vec<DeliveryView> =
        run_cli_json(&bin, &base_url, ["deliveries", "list", "--limit", "1"])?;
    let _: Vec<DeliveryView> = run_cli_json(
        &bin,
        &base_url,
        ["deliveries", "dead-letter", "--limit", "1"],
    )?;

    for path in [
        "/v1/agents/summaries",
        "/v1/assets",
        "/v1/deliveries",
        "/v1/deliveries/dead-letter",
        "/v1/personas",
        "/v1/questions",
        "/v1/runs",
        "/v1/schedules",
        "/v1/sessions",
        "/v1/sessions/page-a/questions",
        "/v1/sessions/page-a/tasks",
    ] {
        let legacy_limited: Value = client
            .get(format!("{base_url}{path}?limit=1"))
            .send()
            .await?
            .error_for_status()?
            .json()
            .await?;
        assert!(
            legacy_limited.is_array(),
            "{path} limit-only request should keep legacy array shape: {legacy_limited}"
        );

        let clamped_page: Value = client
            .get(format!("{base_url}{path}?page=true&limit=999"))
            .send()
            .await?
            .error_for_status()?
            .json()
            .await?;
        assert!(
            clamped_page.get("items").is_some_and(Value::is_array),
            "{path} page request should return items array: {clamped_page}"
        );
        assert_eq!(
            clamped_page["pagination"]["limit"], 100,
            "{path} should clamp excessive pagination limits"
        );
        assert!(
            clamped_page["pagination"]["total_count"].is_number(),
            "{path} should include exact total_count"
        );

        let invalid_limit = client
            .get(format!("{base_url}{path}?page=true&limit=0"))
            .send()
            .await?;
        let problem =
            assert_problem_response(invalid_limit, StatusCode::BAD_REQUEST, "invalid_limit")
                .await?;
        assert_eq!(problem.domain.as_deref(), Some("pagination"));

        let invalid_legacy_limit = client
            .get(format!("{base_url}{path}?limit=0"))
            .send()
            .await?;
        let problem = assert_problem_response(
            invalid_legacy_limit,
            StatusCode::BAD_REQUEST,
            "invalid_limit",
        )
        .await?;
        assert_eq!(problem.domain.as_deref(), Some("pagination"));

        let invalid_cursor = client
            .get(format!("{base_url}{path}?page=true&cursor=%%%"))
            .send()
            .await?;
        let problem =
            assert_problem_response(invalid_cursor, StatusCode::BAD_REQUEST, "invalid_cursor")
                .await?;
        assert_eq!(problem.domain.as_deref(), Some("pagination"));

        let invalid_cursor_without_page = client
            .get(format!("{base_url}{path}?cursor=%%%"))
            .send()
            .await?;
        let problem = assert_problem_response(
            invalid_cursor_without_page,
            StatusCode::BAD_REQUEST,
            "invalid_cursor",
        )
        .await?;
        assert_eq!(problem.domain.as_deref(), Some("pagination"));
    }
    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn events_sse_replay_filters_and_cursor_real_daemon() -> Result<()> {
    let bin = cli_bin()?;
    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let (base_url, mut daemon) = start_openai_mock_route_daemon(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        vec!["SSE_OK".to_string(), "SSE_OK_2".to_string()],
    )
    .await?;
    let client = Client::new();

    let _: SessionView = run_cli_json(&bin, &base_url, ["sessions", "create", "sse-a"])?;
    let completed: RunView = run_cli_json(
        &bin,
        &base_url,
        [
            "sessions",
            "input",
            "sse-a",
            "--wait",
            "Emit one SSE replay marker.",
        ],
    )?;
    assert_eq!(completed.status, DaemonRunStatus::Completed);

    let mut run_stream = client
        .get(format!(
            "{base_url}/v1/runs/{}/stream",
            urlencoding::encode(&completed.run_id)
        ))
        .header("Last-Event-ID", "0")
        .send()
        .await?
        .error_for_status()?;
    let (event_id, event_name, event_data) = next_sse_json_event(&mut run_stream).await?;
    let event_id = event_id.context("replayed run event should include an SSE id")?;
    assert_eq!(event_name, "run_updated");
    assert_eq!(event_data["type"], "run_updated");
    assert_eq!(event_data["run"]["run_id"], completed.run_id);

    let mut session_stream = client
        .get(format!(
            "{base_url}/v1/events/stream?session_id=sse-a&cursor={}",
            event_id.saturating_sub(1)
        ))
        .send()
        .await?
        .error_for_status()?;
    let (replayed_id, replayed_name, replayed_data) =
        next_sse_json_event(&mut session_stream).await?;
    assert_eq!(replayed_id, Some(event_id));
    assert_eq!(replayed_name, "run_updated");
    assert_eq!(replayed_data["run"]["session_id"], "sse-a");

    let mut global_run_stream = client
        .get(format!(
            "{base_url}/v1/events/stream?session_id=sse-a&run_id={}&cursor={}",
            urlencoding::encode(&completed.run_id),
            event_id.saturating_sub(1)
        ))
        .send()
        .await?
        .error_for_status()?;
    let (global_run_id, global_run_name, global_run_data) =
        next_sse_json_event(&mut global_run_stream).await?;
    assert_eq!(global_run_id, Some(event_id));
    assert_eq!(global_run_name, "run_updated");
    assert_eq!(global_run_data["run"]["run_id"], completed.run_id);

    let mut heartbeat_stream = client
        .get(format!("{base_url}/v1/events/stream?cursor={}", u64::MAX))
        .send()
        .await?
        .error_for_status()?;
    let (heartbeat_id, heartbeat_name, heartbeat_data) =
        next_sse_json_event(&mut heartbeat_stream).await?;
    assert_eq!(heartbeat_id, None);
    assert_eq!(heartbeat_name, "heartbeat");
    assert_eq!(heartbeat_data["type"], "heartbeat");

    let mut max_cursor_stream = client
        .get(format!("{base_url}/v1/events/stream?cursor=0"))
        .header("Last-Event-ID", event_id.to_string())
        .send()
        .await?
        .error_for_status()?;
    let second_run: RunView = run_cli_json(
        &bin,
        &base_url,
        [
            "sessions",
            "input",
            "sse-a",
            "--wait",
            "Emit a second SSE replay marker.",
        ],
    )?;
    assert_eq!(second_run.status, DaemonRunStatus::Completed);
    let (guarded_id, _, _) = next_sse_json_event(&mut max_cursor_stream).await?;
    assert!(
        guarded_id.is_some_and(|guarded_id| guarded_id > event_id),
        "query cursor must not override a newer Last-Event-ID"
    );

    let invalid_cursor = client
        .get(format!("{base_url}/v1/events/stream"))
        .header("Last-Event-ID", "not-a-number")
        .send()
        .await?;
    let problem = assert_problem_response(
        invalid_cursor,
        StatusCode::BAD_REQUEST,
        "invalid_event_cursor",
    )
    .await?;
    assert_eq!(problem.domain.as_deref(), Some("events"));
    let invalid_query_cursor = client
        .get(format!("{base_url}/v1/events/stream?cursor=not-a-number"))
        .send()
        .await?;
    let problem = assert_problem_response(
        invalid_query_cursor,
        StatusCode::BAD_REQUEST,
        "invalid_event_cursor",
    )
    .await?;
    assert_eq!(problem.domain.as_deref(), Some("events"));

    stop_daemon(&mut daemon)?;
    let (restarted_base_url, _restarted_daemon) = start_openai_mock_route_daemon(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        vec!["SSE_AFTER_RESTART".to_string()],
    )
    .await?;
    let mut restart_stream = client
        .get(format!(
            "{restarted_base_url}/v1/events/stream?session_id=sse-a"
        ))
        .header("Last-Event-ID", event_id.to_string())
        .send()
        .await?
        .error_for_status()?;
    let (restart_gap_id, restart_gap_name, restart_gap_data) =
        next_sse_json_event(&mut restart_stream).await?;
    assert_eq!(restart_gap_name, "stream_gap");
    assert_eq!(restart_gap_data["type"], "stream_gap");
    assert_eq!(restart_gap_data["reason"], "restart_epoch");
    assert_eq!(restart_gap_data["scope"], "session");
    assert_eq!(restart_gap_data["skipped_is_estimate"], true);
    assert!(
        restart_gap_id.is_some_and(|gap_id| gap_id > event_id),
        "restart gap should carry a safe post-restart resume id"
    );
    assert!(
        restart_gap_data["resume_after_id"]
            .as_str()
            .and_then(|value| value.parse::<u64>().ok())
            .is_some_and(|resume_after_id| resume_after_id > event_id),
        "restart gap should expose a safe resume_after_id: {restart_gap_data}"
    );
    let restarted_run: RunView = run_cli_json(
        &bin,
        &restarted_base_url,
        [
            "sessions",
            "input",
            "sse-a",
            "--wait",
            "Emit an SSE marker after restart.",
        ],
    )?;
    assert_eq!(restarted_run.status, DaemonRunStatus::Completed);
    let (restart_event_id, _, restart_event_data) =
        next_sse_json_event(&mut restart_stream).await?;
    let restart_event_id = restart_event_id.context("restart stream event should include id")?;
    assert!(
        restart_event_id > event_id,
        "restarted daemon must seed fresh SSE ids above pre-restart Last-Event-ID"
    );
    assert!(
        restart_event_data["session_id"] == "sse-a"
            || restart_event_data["trace"]["session_id"] == "sse-a"
            || restart_event_data["run"]["session_id"] == "sse-a"
            || restart_event_data["output"]["session_id"] == "sse-a",
        "unexpected restart SSE event payload: {restart_event_data}"
    );

    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn events_sse_slow_consumer_emits_gap_and_status_lag_real_daemon() -> Result<()> {
    let bin = cli_bin()?;
    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let provider_base_url = spawn_openai_route_mock_server(
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Arc::new(Mutex::new(Vec::new())),
    )
    .await?;
    let routes_path = temp.path().join("routes.toml");
    write_routes_file(&routes_path, &provider_base_url, &provider_base_url)?;
    let (base_url, _daemon) = start_daemon_ready_with_env_and_args(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        &routes_path,
        Some("openrouter"),
        &[
            OsString::from("--event-history-capacity"),
            OsString::from("1"),
        ],
        std::iter::empty::<(&str, &str)>(),
    )?;
    let client = Client::new();
    let mut slow_stream = client
        .get(format!("{base_url}/v1/events/stream"))
        .send()
        .await?
        .error_for_status()?;

    let payload = "x".repeat(16 * 1024);
    for index in 0..64 {
        client
            .post(format!("{base_url}/v1/runtime/system-prompt"))
            .json(&json!({
                "settings": {
                    "append_prompt": format!("{payload}-{index}")
                }
            }))
            .send()
            .await?
            .error_for_status()?;
    }

    let deadline = Instant::now() + Duration::from_secs(15);
    let (gap_id, gap_data) = loop {
        let (id, name, data) = next_sse_json_event(&mut slow_stream).await?;
        if name == "stream_gap" {
            break (id, data);
        }
        if Instant::now() >= deadline {
            bail!("timed out waiting for stream_gap; last SSE event was {name}: {data}");
        }
    };
    assert_eq!(gap_data["type"], "stream_gap");
    assert_eq!(gap_data["reason"], "live_lag");
    assert_eq!(gap_data["scope"], "global");
    assert_eq!(gap_data["skipped_is_estimate"], false);
    assert!(
        gap_data["skipped"]
            .as_u64()
            .is_some_and(|skipped| skipped > 0),
        "live lag gap should report skipped events: {gap_data}"
    );
    let resume_after_id = gap_data["resume_after_id"]
        .as_str()
        .and_then(|value| value.parse::<u64>().ok())
        .context("live lag gap should include a numeric resume_after_id")?;
    assert_eq!(
        gap_id,
        Some(resume_after_id),
        "live lag gap id should be the advertised resume cursor"
    );

    let status = client
        .get(format!("{base_url}/v1/status"))
        .send()
        .await?
        .error_for_status()?
        .json::<DaemonStatusView>()
        .await?;
    assert_eq!(status.events.history_capacity, 1);
    assert!(
        status.events.stream_lagged_event_count > 0,
        "status should expose slow-consumer lag: {:#?}",
        status.events
    );
    assert!(status.events.tail_event_id_cursor.is_some());
    let raw_status = client
        .get(format!("{base_url}/v1/status"))
        .send()
        .await?
        .error_for_status()?
        .json::<Value>()
        .await?;
    let raw_events_status = &raw_status["events"];
    for field in [
        "oldest_event_id",
        "newest_event_id",
        "next_event_id",
        "scope_eviction_floor_id",
        "tail_event_id_cursor",
    ] {
        assert!(
            raw_events_status[field].is_string(),
            "status.events.{field} should serialize as a decimal string: {raw_status:#}"
        );
    }

    Ok(())
}

