#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn control_plane_problem_details_matrix_real_daemon() -> Result<()> {
    let bin = cli_bin()?;
    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let admin_token = "admin-contract";
    let readonly_token = "readonly-contract";
    let (base_url, _daemon) = start_auth_openai_mock_route_daemon(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        admin_token,
        readonly_token,
    )
    .await?;
    let client = Client::new();

    let missing_token = client.get(format!("{base_url}/v1/runtime")).send().await?;
    let problem =
        assert_problem_response(missing_token, StatusCode::UNAUTHORIZED, "missing_token").await?;
    assert_eq!(problem.domain.as_deref(), Some("auth"));

    let readonly_denied = client
        .post(format!("{base_url}/v1/sessions"))
        .bearer_auth(readonly_token)
        .json(&json!({"session_id": "readonly-denied"}))
        .send()
        .await?;
    let problem = assert_problem_response(
        readonly_denied,
        StatusCode::FORBIDDEN,
        "insufficient_access",
    )
    .await?;
    assert_eq!(problem.domain.as_deref(), Some("auth"));

    let missing_session = client
        .get(format!("{base_url}/v1/sessions/missing-session"))
        .bearer_auth(admin_token)
        .send()
        .await?;
    let problem =
        assert_problem_response(missing_session, StatusCode::NOT_FOUND, "session_not_found")
            .await?;
    assert_eq!(problem.domain.as_deref(), Some("sessions"));

    let wrong_method_authorized = client
        .post(format!("{base_url}/v1/status"))
        .bearer_auth(admin_token)
        .send()
        .await?;
    let allow_header = wrong_method_authorized
        .headers()
        .get(header::ALLOW)
        .context("authorized 405 should preserve Allow header")?
        .to_str()?
        .to_string();
    assert!(allow_header.contains("GET"));
    let problem = assert_problem_response(
        wrong_method_authorized,
        StatusCode::METHOD_NOT_ALLOWED,
        "method_not_allowed",
    )
    .await?;
    assert_eq!(problem.domain.as_deref(), None);

    let wrong_method_missing_token = client.post(format!("{base_url}/v1/status")).send().await?;
    let problem = assert_problem_response(
        wrong_method_missing_token,
        StatusCode::UNAUTHORIZED,
        "missing_token",
    )
    .await?;
    assert_eq!(problem.domain.as_deref(), Some("auth"));

    let invalid_json = client
        .post(format!("{base_url}/v1/sessions"))
        .bearer_auth(admin_token)
        .header(header::CONTENT_TYPE, "application/json")
        .body("{")
        .send()
        .await?;
    assert_problem_response(invalid_json, StatusCode::BAD_REQUEST, "bad_request").await?;

    let persona_payload = json!({
        "persona_id": "contract-persona",
        "display_name": "Contract Persona",
        "soul": "first"
    });
    let first_persona = client
        .post(format!("{base_url}/v1/personas"))
        .bearer_auth(admin_token)
        .json(&persona_payload)
        .send()
        .await?;
    assert_eq!(first_persona.status(), StatusCode::CREATED);
    let duplicate_persona = client
        .post(format!("{base_url}/v1/personas"))
        .bearer_auth(admin_token)
        .json(&persona_payload)
        .send()
        .await?;
    let problem = assert_problem_response(
        duplicate_persona,
        StatusCode::CONFLICT,
        "persona_already_exists",
    )
    .await?;
    assert_eq!(problem.domain.as_deref(), Some("personas"));

    let oversized = format!("{{\"session_id\":\"{}\"}}", "x".repeat(25 * 1024 * 1024));
    let oversized_response = client
        .post(format!("{base_url}/v1/sessions"))
        .bearer_auth(admin_token)
        .header(header::CONTENT_TYPE, "application/json")
        .body(oversized)
        .send()
        .await?;
    assert_problem_response(
        oversized_response,
        StatusCode::PAYLOAD_TOO_LARGE,
        "payload_too_large",
    )
    .await?;
    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn cli_json_matches_http_for_major_commands() -> Result<()> {
    let bin = cli_bin()?;
    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let (base_url, _daemon) =
        start_openai_mock_route_daemon(&bin, &temp, &state_root, &workspace_root, Vec::new())
            .await?;
    let client = Client::new();

    let created: SessionView = run_cli_json(&bin, &base_url, ["sessions", "create", "golden"])?;
    assert_eq!(created.session_id, "golden");

    for (cli_args, http_path) in [
        (vec!["capabilities"], "/v1/capabilities"),
        (vec!["runtime", "get"], "/v1/runtime"),
        (vec!["sessions", "list"], "/v1/sessions"),
        (vec!["sessions", "get", "golden"], "/v1/sessions/golden"),
        (vec!["runs", "list"], "/v1/runs"),
        (vec!["tasks", "list", "golden"], "/v1/sessions/golden/tasks"),
        (vec!["agents", "summaries"], "/v1/agents/summaries"),
        (vec!["agents", "audit"], "/v1/agents/audit"),
    ] {
        let cli_value: Value = run_cli_json(&bin, &base_url, cli_args)?;
        let http_value: Value = client
            .get(format!("{base_url}{http_path}"))
            .send()
            .await?
            .json()
            .await?;
        assert_eq!(
            cli_value, http_value,
            "CLI differed from HTTP for {http_path}"
        );
    }
    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn cli_status_accepts_legacy_status_shape_from_old_daemon() -> Result<()> {
    let bin = cli_bin()?;
    let listener = TcpListener::bind("127.0.0.1:0").await?;
    let base_url = format!("http://{}", listener.local_addr()?);
    let router = Router::new()
        .route(
            "/v1/status",
            get(|| async {
                Json(json!({
                    "status": "ready",
                    "ready": true,
                    "capabilities": {
                        "control_plane_version": "legacy",
                        "approvals": true,
                        "sidechains": true,
                        "mailboxes": true,
                        "session_events": true,
                        "restart_restore": true,
                        "live_events": true
                    }
                }))
            }),
        )
        .route(
            "/v1/runtime",
            get(|| async { Json(RuntimeSettingsView::default()) }),
        )
        .route(
            "/v1/sessions",
            get(|| async { Json(Vec::<SessionViewSummary>::new()) }),
        );
    tokio::spawn(async move {
        axum::serve(listener, router)
            .await
            .expect("fake legacy status server");
    });

    let status: DaemonStatusView = run_cli_json(&bin, &base_url, ["status"])?;
    assert_eq!(status.capabilities.control_plane_version, "legacy");
    assert!(
        status
            .health
            .warnings
            .iter()
            .any(|warning| warning.code == "legacy_status_snapshot")
    );
    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn cli_status_matches_mixed_run_and_task_state_on_a_real_daemon() -> Result<()> {
    let bin = cli_bin()?;
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let provider_base_url = spawn_openai_route_mock_server(
        vec![
            openai_tool_call_response(
                "bash",
                json!({
                    "command": "printf 'STATUS-BLOCKED\\n'",
                    "description": "status approval blocker"
                }),
            ),
            openai_tool_call_response(
                "ask_user_question",
                json!({
                    "questions": [{
                        "id": "focus",
                        "header": "Focus",
                        "question": "Which status path should be checked?",
                        "options": [
                            {"id": "runs", "label": "runs"},
                            {"id": "tasks", "label": "tasks"}
                        ]
                    }]
                }),
            ),
            concat!(
                "event: response.failed\n",
                "data: {\"type\":\"response.failed\",\"response\":{\"error\":{\"message\":\"status e2e failure\",\"type\":\"invalid_request_error\",\"code\":\"status_e2e_failure\"}}}\n\n"
            )
            .to_string(),
            openai_tool_call_response(
                "bash",
                json!({
                    "command": "for i in $(seq 1 30); do echo STATUS-TASK-$i; sleep 1; done",
                    "run_in_background": true,
                    "description": "status live background shell"
                }),
            ),
            openai_text_response("STATUS_TASK_READY"),
        ],
        Vec::new(),
        Vec::new(),
        captured_requests.clone(),
    )
    .await?;

    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let routes_path = temp.path().join("routes.toml");
    write_routes_file(&routes_path, &provider_base_url, &provider_base_url)?;

    let (base_url, _daemon) = start_daemon_ready_with_env(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        &routes_path,
        None,
        [
            ("KHEISH_QUEUED_RUN_LAG_WARNING_THRESHOLD_MS", "1"),
            ("KHEISH_STALE_NON_TERMINAL_RUN_THRESHOLD_MS", "1"),
        ],
    )?;
    let _: RuntimeSettingsView =
        run_cli_json(&bin, &base_url, ["runtime", "set-debug-level", "full"])?;

    for session_id in [
        "status-blocked",
        "status-question",
        "status-failed",
        "status-task",
    ] {
        let _: SessionView = run_cli_json(&bin, &base_url, ["sessions", "create", session_id])?;
    }

    let blocked_run: RunView = run_cli_json(
        &bin,
        &base_url,
        [
            "sessions",
            "input",
            "status-blocked",
            "Keep this run waiting on approval.",
        ],
    )?;
    let blocked_run = wait_for_run_status(
        &bin,
        &base_url,
        &blocked_run.run_id,
        &[DaemonRunStatus::WaitingForApproval],
    )
    .await?;
    assert_eq!(blocked_run.status, DaemonRunStatus::WaitingForApproval);

    let queued_run: RunView = run_cli_json(
        &bin,
        &base_url,
        [
            "sessions",
            "input",
            "status-blocked",
            "Queue behind the approval-gated run.",
        ],
    )?;
    let queued_run = wait_for_run_status(
        &bin,
        &base_url,
        &queued_run.run_id,
        &[DaemonRunStatus::Queued],
    )
    .await?;
    assert_eq!(queued_run.status, DaemonRunStatus::Queued);

    let question_run: RunView = run_cli_json(
        &bin,
        &base_url,
        [
            "sessions",
            "input",
            "status-question",
            "Ask one structured question.",
        ],
    )?;
    let question_run = wait_for_run_status(
        &bin,
        &base_url,
        &question_run.run_id,
        &[DaemonRunStatus::WaitingForUserQuestion],
    )
    .await?;
    assert_eq!(question_run.status, DaemonRunStatus::WaitingForUserQuestion);

    let failed_run: RunView = run_cli_json(
        &bin,
        &base_url,
        [
            "sessions",
            "input",
            "status-failed",
            "Trigger one provider failure.",
        ],
    )?;
    let failed_run = wait_for_run_status(
        &bin,
        &base_url,
        &failed_run.run_id,
        &[DaemonRunStatus::Failed],
    )
    .await?;
    assert_eq!(failed_run.status, DaemonRunStatus::Failed);

    let task_run: RunView = run_cli_json(
        &bin,
        &base_url,
        [
            "sessions",
            "input",
            "status-task",
            "Launch one status background task.",
        ],
    )?;
    let task_run = wait_for_run_status(
        &bin,
        &base_url,
        &task_run.run_id,
        &[DaemonRunStatus::WaitingForApproval],
    )
    .await?;
    let approvals: Value = run_cli_json(
        &bin,
        &base_url,
        ["approvals", "list", "--session-id", "status-task"],
    )?;
    let task_request_id = approvals[0]["request"]["id"]
        .as_str()
        .ok_or_else(|| anyhow!("missing task approval request id"))?
        .to_string();
    let task_completed: RunView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("approvals"),
            OsString::from("allow"),
            OsString::from("status-task"),
            OsString::from(task_request_id),
            OsString::from("--justification"),
            OsString::from("approved by status e2e"),
            OsString::from("--wait"),
            OsString::from("--poll-interval-ms"),
            OsString::from("100"),
        ],
    )?;
    assert_eq!(task_run.status, DaemonRunStatus::WaitingForApproval);
    assert_eq!(task_completed.status, DaemonRunStatus::Completed);

    let task_records: Vec<TaskRecord> =
        run_cli_json(&bin, &base_url, ["tasks", "list", "status-task"])?;
    let task = task_records
        .iter()
        .find(|task| task.title.contains("status live background shell"))
        .ok_or_else(|| anyhow!("missing status background shell task"))?;

    let status_started = Instant::now();
    let status: DaemonStatusView = run_cli_json(&bin, &base_url, ["status"])?;
    let status_elapsed = status_started.elapsed();
    let runs: Vec<RunView> = run_cli_json(&bin, &base_url, ["runs", "list"])?;
    let questions: Vec<PendingQuestionView> = run_cli_json(&bin, &base_url, ["questions", "list"])?;

    assert_eq!(status.runs.total, runs.len());
    assert_eq!(
        status.runs.queued,
        runs.iter()
            .filter(|run| run.status == DaemonRunStatus::Queued)
            .count()
    );
    assert_eq!(
        status.runs.waiting_for_approval,
        runs.iter()
            .filter(|run| run.status == DaemonRunStatus::WaitingForApproval)
            .count()
    );
    assert_eq!(
        status.runs.waiting_for_user_question,
        runs.iter()
            .filter(|run| run.status == DaemonRunStatus::WaitingForUserQuestion)
            .count()
    );
    assert_eq!(
        status.runs.failed,
        runs.iter()
            .filter(|run| run.status == DaemonRunStatus::Failed)
            .count()
    );
    assert_eq!(status.runs.queued, 1);
    assert_eq!(
        status.runs.oldest_queued_run_id.as_deref(),
        Some(queued_run.run_id.as_str())
    );
    assert!(status.runs.oldest_queued_run_age_ms.is_some());
    assert_eq!(status.runs.queued_run_lag_threshold_ms, 1);
    assert_eq!(status.runs.stale_non_terminal_run_threshold_ms, 1);
    assert_eq!(status.runs.max_session_queue_depth, 1);
    assert!(status.runs.oldest_queued_run_age_ms.unwrap_or_default() > 1);
    assert!(status.runs.stale_non_terminal_run_count > 0);
    assert!(
        status
            .runs
            .stale_non_terminal_run_ids
            .iter()
            .any(|run_id| run_id == &blocked_run.run_id || run_id == &queued_run.run_id)
    );
    assert_eq!(status.runs.waiting_for_approval, 1);
    assert_eq!(status.runs.waiting_for_user_question, 1);
    assert_eq!(status.runs.failed, 1);
    assert_eq!(status.runs.pending_question_count, questions.len());
    assert_eq!(status.tasks.total, task_records.len());
    assert_eq!(status.tasks.in_progress, 1);
    assert_eq!(status.tasks.live_background_shell_task_count, 1);
    assert!(status.storage.ok);
    assert_eq!(status.provider_readiness.error_route_count, 0);
    assert!(status.provider_readiness.active_route_ready);
    assert!(status.events.history_capacity > 0);
    assert!(status.events.retained_event_count > 0);
    assert!(status.events.newest_event_id.is_some());
    assert!(status.events.replay_buffer_utilization_percent <= 100);
    assert!(
        status.health.snapshot_duration_ms < 3_000,
        "status snapshot reported slow server-side duration: {} ms",
        status.health.snapshot_duration_ms
    );
    assert!(
        status_elapsed < Duration::from_secs(3),
        "status CLI over mixed real-daemon state took {status_elapsed:?}"
    );
    let warning_codes = status
        .health
        .warnings
        .iter()
        .map(|warning| warning.code.as_str())
        .collect::<Vec<_>>();
    assert!(warning_codes.contains(&"debug_capture_full"));
    assert!(warning_codes.contains(&"failed_runs"));
    assert!(warning_codes.contains(&"queued_run_lag"));
    assert!(warning_codes.contains(&"stale_non_terminal_runs"));
    assert!(warning_codes.contains(&"live_background_shell_tasks"));

    let stopped: TaskRecord = run_cli_json(
        &bin,
        &base_url,
        [
            "tasks",
            "stop",
            "status-task",
            task.id.as_str(),
            "--reason",
            "status e2e cleanup",
        ],
    )?;
    assert_eq!(stopped.status, TaskStatus::Cancelled);

    let requests = wait_for_captured_route_requests(&captured_requests, 5).await?;
    assert_eq!(requests.len(), 5);
    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn legacy_serve_with_http_auth_and_openai_run_works_against_a_real_daemon() -> Result<()> {
    let bin = cli_bin()?;
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let openai_base_url =
        spawn_openai_raw_mock_server(OPENAI_OK_RESPONSE, captured_requests.clone()).await?;

    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let bind = reserve_bind_address()?;
    let daemon = start_legacy_daemon_with_env_and_args(
        &bin,
        &temp,
        &bind,
        &state_root,
        &workspace_root,
        &[
            OsString::from("--provider"),
            OsString::from("openai"),
            OsString::from("--api-key"),
            OsString::from("sk-legacy"),
            OsString::from("--openai-base-url"),
            OsString::from(openai_base_url.clone()),
            OsString::from("--http-auth-mode"),
            OsString::from("bearer"),
            OsString::from("--http-admin-token"),
            OsString::from("admin-secret"),
            OsString::from("--http-readonly-token"),
            OsString::from("readonly-secret"),
        ],
        std::iter::empty::<(&str, &str)>(),
    )?;
    let base_url = format!("http://{bind}");
    wait_for_daemon_ready_with_env(
        &bin,
        &base_url,
        &daemon,
        [("KHEISH_DAEMON_TOKEN", "admin-secret")],
    )?;

    let unauthorized = run_cli_output(&bin, &base_url, ["runtime", "get"])?;
    assert!(
        !unauthorized.status.success(),
        "runtime get should require an auth token"
    );
    let unauthorized_stderr = String::from_utf8_lossy(&unauthorized.stderr);
    assert!(
        unauthorized_stderr.contains("401") || unauthorized_stderr.contains("unauthorized"),
        "unexpected unauthorized stderr:\n{unauthorized_stderr}"
    );

    let runtime: RuntimeSettingsView = run_cli_json_with_env(
        &bin,
        &base_url,
        ["runtime", "get"],
        [("KHEISH_DAEMON_TOKEN", "readonly-secret")],
    )?;
    assert_eq!(runtime.provider.as_deref(), Some("openai"));
    assert_eq!(runtime.route_id.as_deref(), Some("openai"));

    let readonly_create = run_cli_output_with_env(
        &bin,
        &base_url,
        ["sessions", "create", "readonly-denied"],
        [("KHEISH_DAEMON_TOKEN", "readonly-secret")],
    )?;
    assert!(
        !readonly_create.status.success(),
        "readonly token must not create sessions"
    );
    let readonly_stderr = String::from_utf8_lossy(&readonly_create.stderr);
    assert!(
        readonly_stderr.contains("403") || readonly_stderr.contains("forbidden"),
        "unexpected readonly stderr:\n{readonly_stderr}"
    );

    let _: SessionView = run_cli_json_with_env(
        &bin,
        &base_url,
        ["sessions", "create", "legacy-demo"],
        [("KHEISH_DAEMON_TOKEN", "admin-secret")],
    )?;
    let completed: RunView = run_cli_json_with_env(
        &bin,
        &base_url,
        [
            "sessions",
            "input",
            "legacy-demo",
            "Reply with ok.",
            "--wait",
        ],
        [("KHEISH_DAEMON_TOKEN", "admin-secret")],
    )?;
    assert_eq!(completed.status, DaemonRunStatus::Completed);
    assert!(
        completed
            .outputs
            .iter()
            .any(|output| output.content.contains("ok"))
    );

    let requests = wait_for_captured_requests(&captured_requests, 1).await?;
    assert!(
        requests
            .iter()
            .any(|request| request.contains("Reply with ok.")),
        "expected a legacy OpenAI request body"
    );

    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn legacy_serve_route_scopes_gate_public_route_ids_on_a_real_daemon() -> Result<()> {
    let bin = cli_bin()?;
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let openai_base_url =
        spawn_openai_raw_mock_server(OPENAI_OK_RESPONSE, captured_requests.clone()).await?;

    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let bind = reserve_bind_address()?;
    let daemon = start_legacy_daemon_with_env_and_args(
        &bin,
        &temp,
        &bind,
        &state_root,
        &workspace_root,
        &[
            OsString::from("--provider"),
            OsString::from("openai"),
            OsString::from("--api-key"),
            OsString::from("sk-legacy"),
            OsString::from("--openai-base-url"),
            OsString::from(openai_base_url.clone()),
            OsString::from("--http-auth-mode"),
            OsString::from("bearer"),
            OsString::from("--http-admin-token"),
            OsString::from("admin-secret"),
        ],
        std::iter::empty::<(&str, &str)>(),
    )?;
    let base_url = format!("http://{bind}");
    wait_for_daemon_ready_with_env(
        &bin,
        &base_url,
        &daemon,
        [("KHEISH_DAEMON_TOKEN", "admin-secret")],
    )?;

    let denied: SessionView = run_cli_json_with_env(
        &bin,
        &base_url,
        vec![
            OsString::from("sessions"),
            OsString::from("create"),
            OsString::from("legacy-route-scope"),
            OsString::from("--credential-scope-json"),
            OsString::from(r#"{"route_deny":["openai"]}"#),
        ],
        [("KHEISH_DAEMON_TOKEN", "admin-secret")],
    )?;
    assert_eq!(
        denied.credential_scope.route_deny,
        vec!["openai".to_string()]
    );

    let denied_run: RunView = run_cli_json_with_env(
        &bin,
        &base_url,
        vec![
            OsString::from("sessions"),
            OsString::from("input"),
            OsString::from("legacy-route-scope"),
            OsString::from("This legacy route should be blocked."),
        ],
        [("KHEISH_DAEMON_TOKEN", "admin-secret")],
    )?;
    let denied_completed: RunView = run_cli_json_with_env(
        &bin,
        &base_url,
        vec![
            OsString::from("runs"),
            OsString::from("wait"),
            OsString::from(denied_run.run_id.clone()),
        ],
        [("KHEISH_DAEMON_TOKEN", "admin-secret")],
    )?;
    assert_eq!(denied_completed.status, DaemonRunStatus::Failed);
    assert!(
        denied_completed
            .error
            .as_deref()
            .is_some_and(|error| error.contains("credential scope blocks route openai")),
        "unexpected denied run error: {:?}",
        denied_completed.error
    );
    tokio::time::sleep(Duration::from_millis(250)).await;
    assert_eq!(
        captured_requests.lock().len(),
        0,
        "blocked legacy route should not reach the upstream provider"
    );

    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn legacy_serve_additional_image_backend_respects_session_credential_scope_on_a_real_daemon()
-> Result<()> {
    let bin = cli_bin()?;
    let primary_requests = Arc::new(Mutex::new(Vec::new()));
    let openai_base_url = spawn_openai_route_mock_server(
        vec![
            openai_tool_call_response(
                "generate_image",
                json!({
                    "prompt": "Render the blocked image.",
                    "count": 1,
                    "provider": "google",
                }),
            ),
            openai_text_response("LEGACY_IMAGE_SCOPE_OK"),
        ],
        Vec::new(),
        Vec::new(),
        primary_requests.clone(),
    )
    .await?;
    let google_requests = Arc::new(Mutex::new(Vec::new()));
    let google_base_url =
        spawn_google_raw_mock_server(GOOGLE_OK_RESPONSE, google_requests.clone()).await?;

    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let bind = reserve_bind_address()?;
    let daemon = start_legacy_daemon_with_env_and_args(
        &bin,
        &temp,
        &bind,
        &state_root,
        &workspace_root,
        &[
            OsString::from("--provider"),
            OsString::from("openai"),
            OsString::from("--api-key"),
            OsString::from("sk-legacy"),
            OsString::from("--openai-base-url"),
            OsString::from(format!("{openai_base_url}/v1/responses")),
            OsString::from("--image-provider"),
            OsString::from("google"),
            OsString::from("--google-api-key"),
            OsString::from("google-image-key"),
            OsString::from("--google-base-url"),
            OsString::from(format!("{google_base_url}/v1beta")),
            OsString::from("--google-image-model"),
            OsString::from("gemini-3-pro-image-preview"),
        ],
        std::iter::empty::<(&str, &str)>(),
    )?;
    let base_url = format!("http://{bind}");
    wait_for_daemon_ready_with_env(&bin, &base_url, &daemon, std::iter::empty::<(&str, &str)>())?;

    let session: SessionView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("sessions"),
            OsString::from("create"),
            OsString::from("legacy-image-scope"),
            OsString::from("--credential-scope-json"),
            OsString::from(r#"{"route_allow":["openai"]}"#),
        ],
    )?;
    assert_eq!(
        session.credential_scope.route_allow,
        vec!["openai".to_string()]
    );

    let run: RunView = run_cli_json(
        &bin,
        &base_url,
        [
            "sessions",
            "input",
            "legacy-image-scope",
            "Generate the blocked image.",
        ],
    )?;
    let completed: RunView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("runs"),
            OsString::from("wait"),
            OsString::from(run.run_id.clone()),
        ],
    )?;
    assert!(
        matches!(
            completed.status,
            DaemonRunStatus::Completed | DaemonRunStatus::Failed
        ),
        "unexpected legacy image status: {:?}",
        completed.status
    );
    tokio::time::sleep(Duration::from_millis(250)).await;
    let primary_requests = primary_requests.lock().clone();
    assert_eq!(
        primary_requests
            .iter()
            .filter(|request| request.path == "/v1/responses")
            .count(),
        2,
        "primary OpenAI route should receive the tool-calling request and the follow-up turn"
    );
    assert!(
        primary_requests.iter().any(|request| request
            .body
            .contains("credential scope blocks route google")),
        "follow-up provider turn should include the blocked image route error"
    );
    assert_eq!(
        google_requests.lock().len(),
        0,
        "blocked legacy image backend should not reach the upstream provider"
    );
    if completed.status == DaemonRunStatus::Completed {
        assert!(
            completed
                .outputs
                .iter()
                .any(|output| output.content.contains("LEGACY_IMAGE_SCOPE_OK"))
        );
    } else {
        assert!(
            completed
                .error
                .as_deref()
                .is_some_and(|error| error.contains("credential scope blocks route google")),
            "unexpected legacy image failure: {:?}",
            completed.error
        );
    }

    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn healthz_and_readyz_remain_public_when_control_plane_auth_requires_bearer() -> Result<()> {
    let bin = cli_bin()?;
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let openai_base_url =
        spawn_openai_raw_mock_server(OPENAI_OK_RESPONSE, captured_requests.clone()).await?;

    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let bind = reserve_bind_address()?;
    let daemon = start_legacy_daemon_with_env_and_args(
        &bin,
        &temp,
        &bind,
        &state_root,
        &workspace_root,
        &[
            OsString::from("--provider"),
            OsString::from("openai"),
            OsString::from("--api-key"),
            OsString::from("sk-health"),
            OsString::from("--openai-base-url"),
            OsString::from(openai_base_url),
            OsString::from("--http-auth-mode"),
            OsString::from("bearer"),
            OsString::from("--http-admin-token"),
            OsString::from("admin-secret"),
        ],
        std::iter::empty::<(&str, &str)>(),
    )?;
    let base_url = format!("http://{bind}");
    wait_for_daemon_ready_with_env(
        &bin,
        &base_url,
        &daemon,
        [("KHEISH_DAEMON_TOKEN", "admin-secret")],
    )?;

    let client = Client::new();
    let health = client.get(format!("{base_url}/healthz")).send().await?;
    assert_eq!(health.status(), StatusCode::OK);
    assert_eq!(health.text().await?, "ok\n");

    let ready = client.get(format!("{base_url}/readyz")).send().await?;
    assert_eq!(ready.status(), StatusCode::OK);
    assert_eq!(ready.text().await?, "ready\n");

    let unauthorized = client.get(format!("{base_url}/v1/runtime")).send().await?;
    assert_eq!(unauthorized.status(), StatusCode::UNAUTHORIZED);

    let authorized = client
        .get(format!("{base_url}/v1/runtime"))
        .bearer_auth("admin-secret")
        .send()
        .await?;
    assert_eq!(authorized.status(), StatusCode::OK);

    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn control_plane_auth_cors_rate_limit_audit_and_token_rotation_on_real_daemon() -> Result<()>
{
    let bin = cli_bin()?;
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let openai_base_url =
        spawn_openai_raw_mock_server(OPENAI_OK_RESPONSE, captured_requests.clone()).await?;

    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let admin_token_file = temp.path().join("admin.token");
    let read_only_token_file = temp.path().join("readonly.token");
    fs::write(&admin_token_file, "admin-version-one\n")?;
    fs::write(&read_only_token_file, "readonly-version-one\n")?;
    let bind = reserve_bind_address()?;
    let daemon = start_legacy_daemon_with_env_and_args(
        &bin,
        &temp,
        &bind,
        &state_root,
        &workspace_root,
        &[
            OsString::from("--provider"),
            OsString::from("openai"),
            OsString::from("--api-key"),
            OsString::from("sk-auth-cors"),
            OsString::from("--openai-base-url"),
            OsString::from(openai_base_url),
            OsString::from("--http-auth-mode"),
            OsString::from("bearer"),
            OsString::from("--http-admin-token-file"),
            admin_token_file.as_os_str().to_os_string(),
            OsString::from("--http-readonly-token-file"),
            read_only_token_file.as_os_str().to_os_string(),
            OsString::from("--http-cors-allow-origin"),
            OsString::from("http://localhost:5173"),
        ],
        std::iter::empty::<(&str, &str)>(),
    )?;
    let base_url = format!("http://{bind}");
    wait_for_daemon_ready_with_env(
        &bin,
        &base_url,
        &daemon,
        [("KHEISH_DAEMON_TOKEN", "admin-version-one")],
    )?;

    let client = Client::new();
    let read_only_get = client
        .get(format!("{base_url}/v1/runtime"))
        .bearer_auth("readonly-version-one")
        .header("Origin", "http://localhost:5173")
        .send()
        .await?;
    assert_eq!(read_only_get.status(), StatusCode::OK);
    assert_eq!(
        read_only_get
            .headers()
            .get("access-control-allow-origin")
            .and_then(|value| value.to_str().ok()),
        Some("http://localhost:5173")
    );

    let read_only_write = run_cli_output_with_env(
        &bin,
        &base_url,
        ["sessions", "create", "readonly-denied"],
        [("KHEISH_DAEMON_TOKEN", "readonly-version-one")],
    )?;
    assert!(!read_only_write.status.success());
    assert!(
        String::from_utf8_lossy(&read_only_write.stderr).contains("403"),
        "unexpected readonly write stderr:\n{}",
        String::from_utf8_lossy(&read_only_write.stderr)
    );

    fs::write(&admin_token_file, "admin-version-two\n")?;
    fs::write(&read_only_token_file, "readonly-version-two\n")?;
    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        let rotated = client
            .get(format!("{base_url}/v1/runtime"))
            .bearer_auth("admin-version-two")
            .send()
            .await?;
        if rotated.status() == StatusCode::OK {
            break;
        }
        if Instant::now() >= deadline {
            bail!("rotated admin token was not accepted before deadline");
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
    let old_admin = client
        .get(format!("{base_url}/v1/runtime"))
        .bearer_auth("admin-version-one")
        .send()
        .await?;
    assert_eq!(old_admin.status(), StatusCode::UNAUTHORIZED);
    let rotated_read_only = client
        .get(format!("{base_url}/v1/runtime"))
        .bearer_auth("readonly-version-two")
        .send()
        .await?;
    assert_eq!(rotated_read_only.status(), StatusCode::OK);
    let status: DaemonStatusView = run_cli_json_with_env(
        &bin,
        &base_url,
        ["status"],
        [("KHEISH_DAEMON_TOKEN", "admin-version-two")],
    )?;
    assert!(status.control_plane.auth_effective_admin_token_available);
    assert!(
        status
            .control_plane
            .auth_effective_read_only_token_available
    );
    assert_eq!(status.control_plane.auth_token_file_error_count, 0);
    assert!(!status.control_plane.auth_duplicate_token);

    fs::write(&admin_token_file, "\n")?;
    let degraded_status: DaemonStatusView = run_cli_json_with_env(
        &bin,
        &base_url,
        ["status"],
        [("KHEISH_DAEMON_TOKEN", "readonly-version-two")],
    )?;
    assert!(
        !degraded_status
            .control_plane
            .auth_effective_admin_token_available
    );
    assert!(
        degraded_status
            .control_plane
            .auth_effective_read_only_token_available
    );
    assert_eq!(degraded_status.control_plane.auth_token_file_error_count, 1);
    let degraded_codes = degraded_status
        .health
        .warnings
        .iter()
        .map(|warning| warning.code.as_str())
        .collect::<Vec<_>>();
    assert!(degraded_codes.contains(&"control_plane_admin_auth_unavailable"));
    assert!(degraded_codes.contains(&"control_plane_auth_token_file_unavailable"));
    fs::write(&admin_token_file, "admin-version-two\n")?;
    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        let restored = client
            .get(format!("{base_url}/v1/runtime"))
            .bearer_auth("admin-version-two")
            .send()
            .await?;
        if restored.status() == StatusCode::OK {
            break;
        }
        if Instant::now() >= deadline {
            bail!("admin token was not accepted after status degradation test");
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }

    for path in [
        "/v1/assets/missing/raw",
        "/v1/runs/run-1/debug",
        "/v1/runs/run-1/debug/artifacts/request",
        "/v1/runtime/secrets",
        "/v1/runtime/auth/subjects/session:demo",
        "/v1/runtime/auth/leases/lease-1",
        "/v1/runtime/auth/accounts",
    ] {
        let denied = client
            .get(format!("{base_url}{path}"))
            .bearer_auth("readonly-version-two")
            .send()
            .await?;
        assert_eq!(
            denied.status(),
            StatusCode::FORBIDDEN,
            "read-only token should not read sensitive path {path}"
        );
    }

    fs::write(&admin_token_file, "ambiguous-token\n")?;
    fs::write(&read_only_token_file, "ambiguous-token\n")?;
    let ambiguous = client
        .get(format!("{base_url}/v1/runtime"))
        .bearer_auth("ambiguous-token")
        .send()
        .await?;
    assert_eq!(ambiguous.status(), StatusCode::UNAUTHORIZED);

    fs::write(&admin_token_file, "admin-version-three-distinct\n")?;
    fs::write(&read_only_token_file, "readonly-version-three-distinct\n")?;
    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        let recovered = client
            .get(format!("{base_url}/v1/runtime"))
            .bearer_auth("admin-version-three-distinct")
            .send()
            .await?;
        if recovered.status() == StatusCode::OK {
            break;
        }
        if Instant::now() >= deadline {
            bail!("distinct admin token was not accepted after ambiguous rotation");
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }

    let unauthorized_allowed_origin = client
        .get(format!("{base_url}/v1/runtime"))
        .header("Origin", "http://localhost:5173")
        .send()
        .await?;
    assert_eq!(
        unauthorized_allowed_origin.status(),
        StatusCode::UNAUTHORIZED
    );
    assert_eq!(
        unauthorized_allowed_origin
            .headers()
            .get("access-control-allow-origin")
            .and_then(|value| value.to_str().ok()),
        Some("http://localhost:5173")
    );

    let rejected_origin = client
        .get(format!("{base_url}/v1/runtime"))
        .bearer_auth("admin-version-three-distinct")
        .header("Origin", "http://evil.example")
        .send()
        .await?;
    assert_eq!(rejected_origin.status(), StatusCode::FORBIDDEN);
    assert!(
        rejected_origin
            .headers()
            .get("access-control-allow-origin")
            .is_none()
    );

    let invalid_token = "bad-auth-token-value";
    let mut rate_limited = None;
    for _ in 0..65 {
        let response = client
            .get(format!("{base_url}/v1/runtime"))
            .bearer_auth(invalid_token)
            .send()
            .await?;
        if response.status() == StatusCode::TOO_MANY_REQUESTS {
            rate_limited = Some(response);
            break;
        }
    }
    let rate_limited =
        rate_limited.ok_or_else(|| anyhow!("auth failure rate limit did not trip"))?;
    assert_eq!(
        rate_limited
            .headers()
            .get("retry-after")
            .and_then(|value| value.to_str().ok()),
        Some("60")
    );

    let valid_after_rate_limit = client
        .get(format!("{base_url}/v1/runtime"))
        .bearer_auth("admin-version-three-distinct")
        .send()
        .await?;
    assert_eq!(valid_after_rate_limit.status(), StatusCode::OK);

    let audit_path = state_root.join("control-plane-auth").join("audit.jsonl");
    let audit = fs::read_to_string(&audit_path)
        .with_context(|| format!("missing control-plane auth audit {}", audit_path.display()))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;

        let mode = fs::metadata(&audit_path)?.permissions().mode() & 0o777;
        assert_eq!(mode, 0o600, "control-plane auth audit mode should be 0600");
    }
    assert!(audit.contains("\"event\":\"auth_failure\""));
    assert!(audit.contains("\"event\":\"auth_rate_limited\""));
    assert!(audit.contains("\"event\":\"cors_origin_rejected\""));
    for secret in [
        "admin-version-one",
        "admin-version-two",
        "admin-version-three-distinct",
        "readonly-version-one",
        "readonly-version-two",
        "readonly-version-three-distinct",
        "ambiguous-token",
        invalid_token,
    ] {
        assert!(!audit.contains(secret), "audit leaked secret {secret}");
    }
    let audit_lines = audit.lines().collect::<Vec<_>>();
    assert!(
        audit_lines.len() <= 80,
        "auth audit should stay bounded after rate limiting, got {} lines",
        audit_lines.len()
    );
    for line in audit_lines {
        serde_json::from_str::<serde_json::Value>(line)
            .with_context(|| format!("invalid audit JSONL line: {line}"))?;
    }

    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn doctor_reports_auth_cors_sse_and_hooks_on_a_real_daemon() -> Result<()> {
    let bin = cli_bin()?;
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let openai_base_url =
        spawn_openai_raw_mock_server(OPENAI_OK_RESPONSE, captured_requests.clone()).await?;

    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let bind = reserve_bind_address()?;
    let daemon = start_legacy_daemon_with_env_and_args(
        &bin,
        &temp,
        &bind,
        &state_root,
        &workspace_root,
        &[
            OsString::from("--provider"),
            OsString::from("openai"),
            OsString::from("--api-key"),
            OsString::from("sk-doctor"),
            OsString::from("--openai-base-url"),
            OsString::from(openai_base_url),
            OsString::from("--http-auth-mode"),
            OsString::from("bearer"),
            OsString::from("--http-admin-token"),
            OsString::from("admin-secret"),
            OsString::from("--http-readonly-token"),
            OsString::from("readonly-secret"),
            OsString::from("--http-cors-allow-origin"),
            OsString::from("http://localhost:5173"),
        ],
        std::iter::empty::<(&str, &str)>(),
    )?;
    let base_url = format!("http://{bind}");
    wait_for_daemon_ready_with_env(
        &bin,
        &base_url,
        &daemon,
        [("KHEISH_DAEMON_TOKEN", "admin-secret")],
    )?;

    let unauthorized_output = run_cli_output_with_env(
        &bin,
        &base_url,
        [
            OsString::from("--output"),
            OsString::from("json"),
            OsString::from("doctor"),
        ],
        std::iter::empty::<(&str, &str)>(),
    )?;
    assert_eq!(
        unauthorized_output.status.code(),
        Some(4),
        "unauthorized doctor should preserve the HTTP auth exit code\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&unauthorized_output.stdout),
        String::from_utf8_lossy(&unauthorized_output.stderr)
    );
    let unauthorized: Value = serde_json::from_slice(&unauthorized_output.stdout)?;
    assert_eq!(unauthorized["ok"], Value::Bool(false));
    assert!(
        unauthorized["status_error"]
            .as_str()
            .is_some_and(|error| error.contains("401") || error.contains("Unauthorized")),
        "unexpected unauthorized doctor output: {unauthorized}"
    );
    assert!(
        unauthorized["checks"]
            .as_array()
            .expect("checks")
            .iter()
            .any(|check| check["code"] == Value::String("status_unreachable".to_string())),
        "unauthorized doctor should include status_unreachable: {unauthorized}"
    );

    let doctor: Value = run_cli_json_with_env(
        &bin,
        &base_url,
        ["doctor"],
        [("KHEISH_DAEMON_TOKEN", "readonly-secret")],
    )?;
    assert_eq!(doctor["ok"], Value::Bool(true));
    assert_eq!(doctor["readyz_reachable"], Value::Bool(true));
    assert_eq!(doctor["events_stream_reachable"], Value::Bool(true));
    assert_eq!(
        doctor["status"]["control_plane"]["auth_enabled"],
        Value::Bool(true)
    );
    assert_eq!(
        doctor["status"]["control_plane"]["read_only_token_enabled"],
        Value::Bool(true)
    );
    assert_eq!(
        doctor["status"]["control_plane"]["cors_policy"],
        Value::String("exact".to_string())
    );
    assert_eq!(
        doctor["status"]["control_plane"]["cors_allowed_origin_count"],
        Value::from(1)
    );
    assert!(
        doctor["checks"]
            .as_array()
            .expect("checks")
            .iter()
            .any(
                |check| check["name"] == Value::String("events_sse".to_string())
                    && check["ok"] == Value::Bool(true)
            ),
        "doctor should include an SSE check: {doctor}"
    );
    assert!(
        doctor["checks"]
            .as_array()
            .expect("checks")
            .iter()
            .any(
                |check| check["name"] == Value::String("provider_readiness".to_string())
                    && check["ok"] == Value::Bool(true)
            ),
        "doctor should include provider readiness: {doctor}"
    );
    assert!(
        doctor["checks"]
            .as_array()
            .expect("checks")
            .iter()
            .any(
                |check| check["name"] == Value::String("storage".to_string())
                    && check["ok"] == Value::Bool(true)
            ),
        "doctor should include storage write health: {doctor}"
    );
    assert!(
        doctor["checks"]
            .as_array()
            .expect("checks")
            .iter()
            .any(
                |check| check["name"] == Value::String("control_plane_cors".to_string())
                    && check.get("action").and_then(Value::as_str).is_some()
            ),
        "doctor CORS check should be actionable: {doctor}"
    );

    let client = Client::new();
    let cors_ok = client
        .request(reqwest::Method::OPTIONS, format!("{base_url}/v1/status"))
        .header("Origin", "http://localhost:5173")
        .header("Access-Control-Request-Method", "POST")
        .header(
            "Access-Control-Request-Headers",
            "authorization,content-type",
        )
        .send()
        .await?;
    assert_eq!(cors_ok.status(), StatusCode::NO_CONTENT);
    assert_eq!(
        cors_ok
            .headers()
            .get("access-control-allow-origin")
            .and_then(|value| value.to_str().ok()),
        Some("http://localhost:5173")
    );
    let allow_methods = cors_ok
        .headers()
        .get("access-control-allow-methods")
        .and_then(|value| value.to_str().ok())
        .unwrap_or_default()
        .to_string();
    assert!(allow_methods.contains("GET"));
    assert!(allow_methods.contains("POST"));
    let allow_headers = cors_ok
        .headers()
        .get("access-control-allow-headers")
        .and_then(|value| value.to_str().ok())
        .unwrap_or_default()
        .to_ascii_lowercase();
    assert!(allow_headers.contains("authorization"));
    assert!(allow_headers.contains("content-type"));
    let cors_ok_doctor: Value = run_cli_json_with_env(
        &bin,
        &base_url,
        ["doctor", "--cors-origin", "http://localhost:5173"],
        [("KHEISH_DAEMON_TOKEN", "readonly-secret")],
    )?;
    assert!(
        cors_ok_doctor["checks"]
            .as_array()
            .expect("checks")
            .iter()
            .any(|check| {
                check["name"] == Value::String("control_plane_cors".to_string())
                    && check["ok"] == Value::Bool(true)
                    && check
                        .get("message")
                        .and_then(Value::as_str)
                        .is_some_and(|message| message.contains("accepts origin"))
            }),
        "doctor should confirm the allowed CORS origin: {cors_ok_doctor}"
    );

    let cors_rejected = client
        .request(reqwest::Method::OPTIONS, format!("{base_url}/v1/status"))
        .header("Origin", "http://evil.example")
        .header("Access-Control-Request-Method", "GET")
        .send()
        .await?;
    assert_eq!(cors_rejected.status(), StatusCode::FORBIDDEN);
    let cors_doctor_output = run_cli_output_with_env(
        &bin,
        &base_url,
        [
            OsString::from("--output"),
            OsString::from("json"),
            OsString::from("doctor"),
            OsString::from("--cors-origin"),
            OsString::from("http://evil.example"),
        ],
        [("KHEISH_DAEMON_TOKEN", "readonly-secret")],
    )?;
    assert_eq!(
        cors_doctor_output.status.code(),
        Some(1),
        "doctor with rejected CORS origin should fail with diagnostic exit code\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&cors_doctor_output.stdout),
        String::from_utf8_lossy(&cors_doctor_output.stderr)
    );
    let cors_doctor: Value = serde_json::from_slice(&cors_doctor_output.stdout)?;
    assert_eq!(cors_doctor["ok"], Value::Bool(false));
    assert!(
        cors_doctor["checks"]
            .as_array()
            .expect("checks")
            .iter()
            .any(|check| {
                check["name"] == Value::String("control_plane_cors".to_string())
                    && check["severity"] == Value::String("error".to_string())
                    && check["related_id"] == Value::String(bind.to_string())
                    && check
                        .get("action")
                        .and_then(Value::as_str)
                        .is_some_and(|action| action.contains("--http-cors-allow-origin"))
            }),
        "doctor should surface rejected CORS origin as actionable error: {cors_doctor}"
    );

    let broken_hooks = HookSettings {
        hooks: std::collections::BTreeMap::from([(
            HookEventName::Setup,
            vec![HookDefinition {
                name: "missing-shell".to_string(),
                matcher: None,
                failure_policy: Default::default(),
                executor: HookExecutorConfig::Command {
                    command: "true".to_string(),
                    shell: Some("/definitely/not/kheish-shell".to_string()),
                    timeout_ms: Some(1_000),
                },
            }],
        )]),
    };
    let broken_hooks_path = temp.path().join("doctor-broken-hooks.json");
    fs::write(
        &broken_hooks_path,
        serde_json::to_vec_pretty(&broken_hooks)?,
    )?;
    let _: RuntimeSettingsView = run_cli_json_with_env(
        &bin,
        &base_url,
        vec![
            OsString::from("runtime"),
            OsString::from("hooks"),
            OsString::from("set"),
            OsString::from("--file"),
            broken_hooks_path.into_os_string(),
        ],
        [("KHEISH_DAEMON_TOKEN", "admin-secret")],
    )?;

    let broken_hooks_doctor_output = run_cli_output_with_env(
        &bin,
        &base_url,
        [
            OsString::from("--output"),
            OsString::from("json"),
            OsString::from("doctor"),
        ],
        [("KHEISH_DAEMON_TOKEN", "readonly-secret")],
    )?;
    assert_eq!(
        broken_hooks_doctor_output.status.code(),
        Some(1),
        "doctor should fail when a configured command hook shell cannot spawn\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&broken_hooks_doctor_output.stdout),
        String::from_utf8_lossy(&broken_hooks_doctor_output.stderr)
    );
    let broken_hooks_doctor: Value = serde_json::from_slice(&broken_hooks_doctor_output.stdout)?;
    assert!(
        broken_hooks_doctor["checks"]
            .as_array()
            .expect("checks")
            .iter()
            .any(|check| {
                check["name"] == Value::String("hooks".to_string())
                    && check["severity"] == Value::String("error".to_string())
                    && check
                        .get("message")
                        .and_then(Value::as_str)
                        .is_some_and(|message| message.contains("command hook shell"))
            }),
        "doctor should surface the missing hook shell as actionable hooks error: {broken_hooks_doctor}"
    );

    let hooks = HookSettings {
        hooks: std::collections::BTreeMap::from([(
            HookEventName::Setup,
            vec![HookDefinition {
                name: "doctor-noop".to_string(),
                matcher: None,
                failure_policy: Default::default(),
                executor: HookExecutorConfig::Command {
                    command: "printf sk-hook-secret".to_string(),
                    shell: None,
                    timeout_ms: Some(1_000),
                },
            }],
        )]),
    };
    let hooks_path = temp.path().join("doctor-hooks.json");
    fs::write(&hooks_path, serde_json::to_vec_pretty(&hooks)?)?;
    let _: RuntimeSettingsView = run_cli_json_with_env(
        &bin,
        &base_url,
        vec![
            OsString::from("runtime"),
            OsString::from("hooks"),
            OsString::from("set"),
            OsString::from("--file"),
            hooks_path.into_os_string(),
        ],
        [("KHEISH_DAEMON_TOKEN", "admin-secret")],
    )?;

    let doctor_after_hooks: Value = run_cli_json_with_env(
        &bin,
        &base_url,
        ["doctor"],
        [("KHEISH_DAEMON_TOKEN", "readonly-secret")],
    )?;
    assert_eq!(
        doctor_after_hooks["status"]["runtime"]["hooks"]["hooks"]["setup"][0]["executor"]["command"],
        Value::String("<redacted>".to_string())
    );
    let rendered_doctor_after_hooks = serde_json::to_string(&doctor_after_hooks)?;
    assert!(
        !rendered_doctor_after_hooks.contains("sk-hook-secret"),
        "doctor output should redact hook command contents: {rendered_doctor_after_hooks}"
    );

    let warning_hooks = HookSettings {
        hooks: std::collections::BTreeMap::from([(
            HookEventName::Setup,
            vec![HookDefinition {
                name: "callback-warning".to_string(),
                matcher: None,
                failure_policy: Default::default(),
                executor: HookExecutorConfig::Callback {
                    name: "embedder_callback".to_string(),
                    timeout_ms: Some(1_000),
                },
            }],
        )]),
    };
    let warning_hooks_path = temp.path().join("doctor-warning-hooks.json");
    fs::write(
        &warning_hooks_path,
        serde_json::to_vec_pretty(&warning_hooks)?,
    )?;
    let _: RuntimeSettingsView = run_cli_json_with_env(
        &bin,
        &base_url,
        vec![
            OsString::from("runtime"),
            OsString::from("hooks"),
            OsString::from("set"),
            OsString::from("--file"),
            warning_hooks_path.into_os_string(),
        ],
        [("KHEISH_DAEMON_TOKEN", "admin-secret")],
    )?;
    let doctor_with_warning: Value = run_cli_json_with_env(
        &bin,
        &base_url,
        ["doctor"],
        [("KHEISH_DAEMON_TOKEN", "readonly-secret")],
    )?;
    assert_eq!(doctor_with_warning["ok"], Value::Bool(true));
    assert!(
        doctor_with_warning["warnings"]
            .as_array()
            .expect("warnings")
            .iter()
            .any(|warning| warning
                .as_str()
                .is_some_and(|message| message.contains("callback hook availability"))),
        "doctor should include hook warnings in the top-level warning list: {doctor_with_warning}"
    );
    assert!(
        doctor_with_warning["checks"]
            .as_array()
            .expect("checks")
            .iter()
            .any(|check| {
                check["name"] == Value::String("hooks".to_string())
                    && check["severity"] == Value::String("warning".to_string())
                    && check["related_id"] == Value::String("Setup:callback-warning".to_string())
                    && check.get("action").and_then(Value::as_str).is_some()
            }),
        "doctor should surface actionable hook warning details: {doctor_with_warning}"
    );

    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn doctor_schema_mismatch_exits_8_against_broken_daemon() -> Result<()> {
    let bin = cli_bin()?;
    let listener = TcpListener::bind("127.0.0.1:0").await?;
    let base_url = format!("http://{}", listener.local_addr()?);
    let router = Router::new()
        .route("/v1/status", get(|| async { Json(json!({})) }))
        .route("/readyz", get(|| async { "ok" }))
        .route(
            "/v1/events/stream",
            get(|| async {
                (
                    [(header::CONTENT_TYPE, "text/event-stream")],
                    "event: heartbeat\ndata: {\"type\":\"heartbeat\"}\n\n",
                )
            }),
        );
    tokio::spawn(async move {
        axum::serve(listener, router)
            .await
            .expect("fake broken daemon should serve");
    });

    let output = run_cli_output(
        &bin,
        &base_url,
        [
            OsString::from("--output"),
            OsString::from("json"),
            OsString::from("doctor"),
        ],
    )?;
    assert_eq!(
        output.status.code(),
        Some(8),
        "schema mismatch should keep documented exit code 8\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let doctor: Value = serde_json::from_slice(&output.stdout)?;
    assert_eq!(doctor["ok"], Value::Bool(false));
    assert!(
        doctor["status_error"]
            .as_str()
            .is_some_and(|error| error.contains("failed to decode daemon status response")),
        "doctor should surface status decode failure: {doctor}"
    );
    assert!(
        doctor["checks"]
            .as_array()
            .expect("checks")
            .iter()
            .any(|check| check["code"] == Value::String("status_unreachable".to_string())),
        "schema mismatch doctor should still produce structured status_unreachable check: {doctor}"
    );
    Ok(())
}

