#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn doctor_cors_preflight_does_not_send_authorization_header() -> Result<()> {
    let bin = cli_bin()?;
    let listener = TcpListener::bind("127.0.0.1:0").await?;
    let base_url = format!("http://{}", listener.local_addr()?);
    let status = doctor_status_fixture();
    let router = Router::new()
        .route(
            "/v1/status",
            get({
                let status = status.clone();
                move || {
                    let status = status.clone();
                    async move { Json(status) }
                }
            })
            .options(|headers: HeaderMap| async move {
                if headers.contains_key(header::AUTHORIZATION) {
                    return StatusCode::FORBIDDEN.into_response();
                }
                (
                    StatusCode::NO_CONTENT,
                    [
                        (header::ACCESS_CONTROL_ALLOW_ORIGIN, "http://localhost:5173"),
                        (
                            header::ACCESS_CONTROL_ALLOW_METHODS,
                            "GET,HEAD,POST,PUT,PATCH,DELETE,OPTIONS",
                        ),
                        (
                            header::ACCESS_CONTROL_ALLOW_HEADERS,
                            "authorization,content-type,x-kheish-daemon-token,x-kheish-daemon-url",
                        ),
                    ],
                )
                    .into_response()
            }),
        )
        .route("/readyz", get(|| async { "ok" }))
        .route(
            "/v1/events/stream",
            get(|| async {
                (
                    [(header::CONTENT_TYPE, "text/event-stream")],
                    "event: heartbeat\ndata: {\"type\":\"heartbeat\"}\n\n",
                )
            }),
        );
    tokio::spawn(async move {
        axum::serve(listener, router)
            .await
            .expect("fake CORS auth-sensitive daemon should serve");
    });

    let doctor: Value = run_cli_json_with_env(
        &bin,
        &base_url,
        ["doctor", "--cors-origin", "http://localhost:5173"],
        [("KHEISH_DAEMON_TOKEN", "secret-token")],
    )?;
    assert!(
        doctor["checks"]
            .as_array()
            .expect("checks")
            .iter()
            .any(|check| {
                check["name"] == Value::String("control_plane_cors".to_string())
                    && check["ok"] == Value::Bool(true)
            }),
        "doctor CORS preflight should behave like a browser preflight without Authorization: {doctor}"
    );
    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn doctor_routes_check_auth_readonly_token_exits_4_with_diagnostic() -> Result<()> {
    let bin = cli_bin()?;
    let provider_base_url = spawn_openai_route_mock_server(
        Vec::new(),
        Vec::new(),
        Vec::new(),
        Arc::new(Mutex::new(Vec::new())),
    )
    .await?;

    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let routes_path = temp.path().join("routes.toml");
    write_secret_routes_file(&routes_path, &provider_base_url, &provider_base_url)?;
    let master_key = "0123456789abcdef0123456789abcdef";
    for slot_id in ["openrouter.primary", "openai.primary"] {
        let _: AuthSlotStatus = run_cli_json_with_env(
            &bin,
            "http://127.0.0.1:1",
            vec![
                OsString::from("secrets"),
                OsString::from("set"),
                OsString::from(slot_id),
                OsString::from("--offline"),
                OsString::from("--state-root"),
                state_root.as_os_str().to_os_string(),
                OsString::from("--provider"),
                OsString::from("openai"),
                OsString::from("--value"),
                OsString::from(format!("{slot_id}-key")),
            ],
            [(AUTH_STORE_MASTER_KEY_ENV, master_key)],
        )?;
    }
    let bind = reserve_bind_address()?;
    let daemon = start_daemon_with_env_and_args(
        &bin,
        &temp,
        &bind,
        &state_root,
        &workspace_root,
        &routes_path,
        Some("openrouter"),
        &[
            OsString::from("--http-auth-mode"),
            OsString::from("bearer"),
            OsString::from("--http-admin-token"),
            OsString::from("admin-secret"),
            OsString::from("--http-readonly-token"),
            OsString::from("readonly-secret"),
        ],
        [(AUTH_STORE_MASTER_KEY_ENV, master_key)],
    )?;
    let base_url = format!("http://{bind}");
    wait_for_daemon_ready_with_env(
        &bin,
        &base_url,
        &daemon,
        [("KHEISH_DAEMON_TOKEN", "admin-secret")],
    )?;

    let output = run_cli_output_with_env(
        &bin,
        &base_url,
        [
            OsString::from("--output"),
            OsString::from("json"),
            OsString::from("doctor"),
            OsString::from("routes"),
            OsString::from("--check-auth"),
        ],
        [("KHEISH_DAEMON_TOKEN", "readonly-secret")],
    )?;
    assert_eq!(
        output.status.code(),
        Some(4),
        "doctor routes --check-auth should preserve readonly auth failure exit code\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let view: Value = serde_json::from_slice(&output.stdout)?;
    assert_eq!(view["ok"], Value::Bool(false));
    assert_eq!(view["auth_checked"], Value::Bool(true));
    assert!(
        view["diagnostics"]
            .as_array()
            .expect("diagnostics")
            .iter()
            .any(|diagnostic| {
                diagnostic["code"] == Value::String("auth_check_failed".to_string())
                    && diagnostic["severity"] == Value::String("error".to_string())
                    && diagnostic
                        .get("message")
                        .and_then(Value::as_str)
                        .is_some_and(|message| {
                            message.contains("failed to check daemon auth slots")
                                && (message.contains("403") || message.contains("forbidden"))
                        })
            }),
        "doctor routes should print an actionable auth_check_failed diagnostic before exiting: {view}"
    );
    let combined = format!(
        "{}\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    assert!(
        !combined.contains("admin-secret") && !combined.contains("readonly-secret"),
        "doctor routes auth failure must not leak control-plane tokens: {combined}"
    );
    Ok(())
}

