#[cfg(unix)]
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn serve_lock_rejects_second_daemon_and_first_stays_healthy() -> Result<()> {
    let bin = cli_bin()?;
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let provider_base_url =
        spawn_openai_raw_mock_server(OPENAI_OK_RESPONSE, captured_requests.clone()).await?;

    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let routes_path = temp.path().join("routes.toml");
    write_routes_file(&routes_path, &provider_base_url, &provider_base_url)?;

    let (base_url, _daemon) =
        start_daemon_ready(&bin, &temp, &state_root, &workspace_root, &routes_path)?;
    let second_bind = reserve_bind_address()?;
    let mut second = start_daemon_with_env_and_args(
        &bin,
        &temp,
        &second_bind,
        &state_root,
        &workspace_root,
        &routes_path,
        Some("openrouter"),
        &[],
        std::iter::empty::<(&str, &str)>(),
    )?;
    let deadline = Instant::now() + Duration::from_secs(5);
    let second_status = loop {
        if let Some(status) = second.child.try_wait()? {
            break status;
        }
        if Instant::now() >= deadline {
            let _ = stop_daemon(&mut second);
            bail!("second daemon did not exit after lock conflict");
        }
        std::thread::sleep(Duration::from_millis(100));
    };
    assert!(
        !second_status.success(),
        "second daemon unexpectedly acquired the same state root lock"
    );
    assert!(
        second.logs().contains("already locked"),
        "second daemon logs should mention the state-root lock: {}",
        second.logs()
    );

    let doctor: Value = run_cli_json(&bin, &base_url, ["doctor"])?;
    assert_eq!(doctor["ok"], Value::Bool(true));
    assert_eq!(doctor["readyz_reachable"], Value::Bool(true));
    assert!(
        doctor["checks"]
            .as_array()
            .expect("checks")
            .iter()
            .any(|check| {
                check["name"] == Value::String("state_root_lock".to_string())
                    && check["severity"] == Value::String("info".to_string())
                    && check
                        .get("message")
                        .and_then(Value::as_str)
                        .is_some_and(|message| message.contains("held via flock"))
            }),
        "doctor should report the held flock state-root lock: {doctor}"
    );

    let lock_path = state_root.join("daemon.lock");
    fs::write(&lock_path, "pid=999999\nmechanism=flock\n")?;
    let doctor_with_stale_marker: Value = run_cli_json(&bin, &base_url, ["doctor"])?;
    assert_eq!(doctor_with_stale_marker["ok"], Value::Bool(true));
    assert!(
        doctor_with_stale_marker["checks"]
            .as_array()
            .expect("checks")
            .iter()
            .any(|check| {
                check["name"] == Value::String("state_root_lock".to_string())
                    && check["severity"] == Value::String("info".to_string())
                    && check["related_id"] == Value::String(lock_path.display().to_string())
                    && check
                        .get("message")
                        .and_then(Value::as_str)
                        .is_some_and(|message| message.contains("held via flock"))
            }),
        "doctor should trust the acquired lock guard, not stale marker contents: {doctor_with_stale_marker}"
    );

    Ok(())
}

