fn start_daemon_ready_with_env<I, K, V>(
    bin: &Path,
    temp: &TempDir,
    state_root: &Path,
    workspace_root: &Path,
    routes_path: &Path,
    default_route: Option<&str>,
    envs: I,
) -> Result<(String, DaemonProcess)>
where
    I: IntoIterator<Item = (K, V)>,
    K: AsRef<std::ffi::OsStr>,
    V: AsRef<std::ffi::OsStr>,
{
    start_daemon_ready_with_env_and_args(
        bin,
        temp,
        state_root,
        workspace_root,
        routes_path,
        default_route,
        &[],
        envs,
    )
}

fn start_daemon_ready_with_env_and_args<I, K, V>(
    bin: &Path,
    temp: &TempDir,
    state_root: &Path,
    workspace_root: &Path,
    routes_path: &Path,
    default_route: Option<&str>,
    extra_args: &[OsString],
    envs: I,
) -> Result<(String, DaemonProcess)>
where
    I: IntoIterator<Item = (K, V)>,
    K: AsRef<std::ffi::OsStr>,
    V: AsRef<std::ffi::OsStr>,
{
    let envs: Vec<(OsString, OsString)> = envs
        .into_iter()
        .map(|(name, value)| (name.as_ref().to_os_string(), value.as_ref().to_os_string()))
        .collect();
    let mut last_error = None;
    for _attempt in 0..5 {
        let bind = reserve_bind_address()?;
        let base_url = format!("http://{bind}");
        let mut daemon = start_daemon_with_env_and_args(
            bin,
            temp,
            &bind,
            state_root,
            workspace_root,
            routes_path,
            default_route,
            extra_args,
            envs.iter().map(|(name, value)| (name, value)),
        )?;
        match wait_for_daemon_ready(bin, &base_url, &daemon) {
            Ok(()) => return Ok((base_url, daemon)),
            Err(error)
                if error.to_string().contains("Address already in use")
                    || daemon.logs().contains("Address already in use") =>
            {
                let _ = stop_daemon(&mut daemon);
                last_error = Some(error);
            }
            Err(error) => {
                let _ = stop_daemon(&mut daemon);
                return Err(error);
            }
        }
    }
    Err(last_error.unwrap_or_else(|| anyhow!("failed to start daemon after repeated bind retries")))
}

fn assert_daemon_startup_fails(
    bin: &Path,
    temp: &TempDir,
    state_root: &Path,
    workspace_root: &Path,
    routes_path: &Path,
    default_route: Option<&str>,
    expected_message: &str,
) -> Result<()> {
    assert_daemon_startup_fails_with_env_and_args(
        bin,
        temp,
        state_root,
        workspace_root,
        routes_path,
        default_route,
        &[],
        std::iter::empty::<(&str, &str)>(),
        expected_message,
    )
}

fn assert_daemon_startup_fails_with_env_and_args<I, K, V>(
    bin: &Path,
    temp: &TempDir,
    state_root: &Path,
    workspace_root: &Path,
    routes_path: &Path,
    default_route: Option<&str>,
    extra_args: &[OsString],
    envs: I,
    expected_message: &str,
) -> Result<()>
where
    I: IntoIterator<Item = (K, V)>,
    K: AsRef<std::ffi::OsStr>,
    V: AsRef<std::ffi::OsStr>,
{
    let bind = reserve_bind_address()?;
    let base_url = format!("http://{bind}");
    let mut daemon = start_daemon_with_env_and_args(
        bin,
        temp,
        &bind,
        state_root,
        workspace_root,
        routes_path,
        default_route,
        extra_args,
        envs,
    )?;
    let error = wait_for_daemon_ready(bin, &base_url, &daemon)
        .expect_err("daemon startup should fail for invalid route capabilities");
    let message = error.to_string();
    let logs = daemon.logs();
    stop_daemon(&mut daemon)?;
    assert!(
        message.contains(expected_message) || logs.contains(expected_message),
        "expected startup failure containing `{expected_message}`\nerror:\n{message}\nlogs:\n{logs}"
    );
    Ok(())
}

