async fn spawn_raw_status_mock_server(
    status: StatusCode,
    response_body: &str,
    content_type: &str,
    captured_requests: Arc<Mutex<Vec<String>>>,
) -> Result<String> {
    let listener = TcpListener::bind("127.0.0.1:0").await?;
    let address = listener.local_addr()?;
    let status_code = status.as_u16();
    let status_reason = status.canonical_reason().unwrap_or("Unknown").to_string();
    let response_body = response_body.to_string();
    let content_type = content_type.to_string();
    tokio::spawn(async move {
        loop {
            let Ok((mut socket, _)) = listener.accept().await else {
                break;
            };
            let captured_requests = captured_requests.clone();
            let response_body = response_body.clone();
            let content_type = content_type.clone();
            let status_reason = status_reason.clone();
            tokio::spawn(async move {
                let mut request = Vec::new();
                let mut buffer = [0_u8; 4096];
                loop {
                    let read = socket
                        .read(&mut buffer)
                        .await
                        .expect("request read should succeed");
                    if read == 0 {
                        break;
                    }
                    request.extend_from_slice(&buffer[..read]);
                    if request.windows(4).any(|window| window == b"\r\n\r\n") {
                        break;
                    }
                }
                let request_text = String::from_utf8(request).expect("request must be utf-8");
                let content_length = request_text
                    .lines()
                    .find_map(|line| {
                        line.split_once(':').and_then(|(name, value)| {
                            name.trim()
                                .eq_ignore_ascii_case("content-length")
                                .then_some(value.trim())
                        })
                    })
                    .and_then(|value| value.parse::<usize>().ok())
                    .unwrap_or_default();
                let body_start = request_text
                    .find("\r\n\r\n")
                    .map(|index| index + 4)
                    .unwrap_or(request_text.len());
                let mut body_bytes = request_text.as_bytes()[body_start..].to_vec();
                while body_bytes.len() < content_length {
                    let read = socket
                        .read(&mut buffer)
                        .await
                        .expect("body read should succeed");
                    if read == 0 {
                        break;
                    }
                    body_bytes.extend_from_slice(&buffer[..read]);
                }
                captured_requests.lock().push(format!(
                    "{request_text}{}",
                    String::from_utf8(body_bytes).expect("body must be utf-8")
                ));
                let response = format!(
                    "HTTP/1.1 {status_code} {status_reason}\r\nContent-Length: {}\r\ncontent-type: {content_type}\r\n\r\n{response_body}",
                    response_body.len(),
                );
                socket
                    .write_all(response.as_bytes())
                    .await
                    .expect("response write should succeed");
            });
        }
    });
    Ok(format!("http://{address}"))
}

async fn spawn_lossy_raw_mock_server(
    response_body: &str,
    content_type: &str,
    captured_request: Arc<Mutex<String>>,
) -> Result<String> {
    let listener = StdTcpListener::bind("127.0.0.1:0")?;
    let address = listener.local_addr()?;
    let response_body = response_body.to_string();
    let content_type = content_type.to_string();
    std::thread::spawn(move || {
        let Ok((mut socket, _)) = listener.accept() else {
            return;
        };
        let mut request = Vec::new();
        let mut buffer = [0_u8; 4096];
        loop {
            let read = socket
                .read(&mut buffer)
                .expect("request read should succeed");
            if read == 0 {
                break;
            }
            request.extend_from_slice(&buffer[..read]);
            if request.windows(4).any(|window| window == b"\r\n\r\n") {
                break;
            }
        }
        let header_end = request
            .windows(4)
            .position(|window| window == b"\r\n\r\n")
            .map(|index| index + 4)
            .unwrap_or(request.len());
        let request_text =
            String::from_utf8(request[..header_end].to_vec()).expect("request must be utf-8");
        let content_length = request_text
            .lines()
            .find_map(|line| {
                line.split_once(':').and_then(|(name, value)| {
                    name.trim()
                        .eq_ignore_ascii_case("content-length")
                        .then_some(value.trim())
                })
            })
            .and_then(|value| value.parse::<usize>().ok())
            .unwrap_or_default();
        let mut body_bytes = request[header_end..].to_vec();
        while body_bytes.len() < content_length {
            let read = socket.read(&mut buffer).expect("body read should succeed");
            if read == 0 {
                break;
            }
            body_bytes.extend_from_slice(&buffer[..read]);
        }
        *captured_request.lock() =
            format!("{request_text}{}", String::from_utf8_lossy(&body_bytes));
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Length: {}\r\ncontent-type: {content_type}\r\n\r\n{response_body}",
            response_body.len(),
        );
        socket
            .write_all(response.as_bytes())
            .expect("response write should succeed");
    });
    Ok(format!("http://{address}"))
}

