struct DelayedOpenAiRouteMockState {
    text_responses: Arc<Mutex<VecDeque<DelayedRouteResponse>>>,
    captured_requests: Arc<Mutex<Vec<CapturedRouteRequest>>>,
}

async fn record_delayed_openai_route_text_request(
    State(state): State<DelayedOpenAiRouteMockState>,
    body: Bytes,
) -> impl IntoResponse {
    state.captured_requests.lock().push(CapturedRouteRequest {
        path: "/v1/responses".to_string(),
        body: String::from_utf8_lossy(&body).into_owned(),
    });
    let response = state
        .text_responses
        .lock()
        .pop_front()
        .unwrap_or_else(|| panic!("missing delayed mock response for /v1/responses"));
    tokio::time::sleep(Duration::from_millis(response.delay_ms)).await;
    (
        StatusCode::OK,
        [(header::CONTENT_TYPE, "text/event-stream")],
        response.body,
    )
        .into_response()
}

async fn spawn_delayed_openai_route_mock_server(
    text_responses: Vec<DelayedRouteResponse>,
    captured_requests: Arc<Mutex<Vec<CapturedRouteRequest>>>,
) -> Result<String> {
    let listener = TcpListener::bind("127.0.0.1:0").await?;
    let address = listener.local_addr()?;
    let app = Router::new()
        .route(
            "/v1/responses",
            post(record_delayed_openai_route_text_request),
        )
        .with_state(DelayedOpenAiRouteMockState {
            text_responses: Arc::new(Mutex::new(VecDeque::from(text_responses))),
            captured_requests,
        });
    tokio::spawn(async move {
        axum::serve(listener, app)
            .await
            .expect("delayed mock provider server should stay healthy");
    });
    Ok(format!("http://{address}"))
}

async fn wait_for_captured_route_requests(
    captured_requests: &Arc<Mutex<Vec<CapturedRouteRequest>>>,
    expected: usize,
) -> Result<Vec<CapturedRouteRequest>> {
    let deadline = tokio::time::Instant::now() + Duration::from_secs(10);
    loop {
        let current = captured_requests.lock().clone();
        if current.len() >= expected {
            return Ok(current);
        }
        if tokio::time::Instant::now() >= deadline {
            let summary = current
                .iter()
                .map(|request| request.path.as_str())
                .collect::<Vec<_>>()
                .join(", ");
            bail!(
                "timed out waiting for {expected} captured provider requests; captured {} requests [{}]",
                current.len(),
                summary
            );
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
}

async fn wait_for_captured_route_request_containing(
    captured_requests: &Arc<Mutex<Vec<CapturedRouteRequest>>>,
    needle: &str,
) -> Result<CapturedRouteRequest> {
    let deadline = tokio::time::Instant::now() + Duration::from_secs(10);
    loop {
        let current = captured_requests.lock().clone();
        if let Some(request) = current
            .into_iter()
            .find(|request| request.body.contains(needle))
        {
            return Ok(request);
        }
        if tokio::time::Instant::now() >= deadline {
            bail!("timed out waiting for a captured provider request containing `{needle}`");
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
}

