async fn wait_for_channel_stimuli<F>(
    bin: &Path,
    base_url: &str,
    channel_id: &str,
    thread_root_message_id: Option<&str>,
    predicate: F,
    description: &str,
) -> Result<Vec<ChannelStimulusView>>
where
    F: Fn(&[ChannelStimulusView]) -> bool,
{
    let deadline = Instant::now() + Duration::from_secs(20);
    loop {
        let mut args = vec![
            OsString::from("channels"),
            OsString::from("stimuli"),
            OsString::from("list"),
            OsString::from(channel_id),
        ];
        if let Some(thread_root_message_id) = thread_root_message_id {
            args.push(OsString::from("--thread-root-message-id"));
            args.push(OsString::from(thread_root_message_id));
        }
        let stimuli: Vec<ChannelStimulusView> = run_cli_json(bin, base_url, args)?;
        if predicate(&stimuli) {
            return Ok(stimuli);
        }
        if Instant::now() >= deadline {
            bail!("timed out waiting for {description} in channel {channel_id}: {stimuli:#?}");
        }
        tokio::time::sleep(Duration::from_millis(150)).await;
    }
}

