fn write_routes_file(path: &Path, openrouter_base_url: &str, openai_base_url: &str) -> Result<()> {
    write_routes_file_with_openai_api_key(path, openrouter_base_url, openai_base_url, "test-key")
}

fn write_routes_file_with_openai_api_key(
    path: &Path,
    openrouter_base_url: &str,
    openai_base_url: &str,
    openai_api_key: &str,
) -> Result<()> {
    fs::write(
        path,
        format!(
            "version = 1\ndefault_route = \"openrouter\"\n\n[routes.openrouter]\ndriver = \"openai\"\ndefault_model = \"openai/gpt-5.4-mini\"\nmodel_support = \"any\"\napi_key = \"test-key\"\nbase_url = \"{openrouter_base_url}/v1/responses\"\n\n[routes.openai]\ndriver = \"openai\"\ndefault_model = \"gpt-5.4\"\napi_key = \"{openai_api_key}\"\nbase_url = \"{openai_base_url}/v1/responses\"\n"
        ),
    )?;
    Ok(())
}

