fn write_sample_png(path: &Path) -> Result<()> {
    let image = ImageBuffer::<Rgb<u8>, Vec<u8>>::from_pixel(8, 8, Rgb([255, 0, 0]));
    let mut cursor = std::io::Cursor::new(Vec::new());
    image.write_to(&mut cursor, image::ImageFormat::Png)?;
    fs::write(path, cursor.into_inner())?;
    Ok(())
}

fn asset_raw_path(state_root: &Path, asset: &AssetView) -> Result<PathBuf> {
    let relative = asset
        .uri
        .strip_prefix("asset://raw/")
        .ok_or_else(|| anyhow!("unexpected raw asset URI {}", asset.uri))?;
    Ok(state_root.join("assets").join("raw").join(relative))
}

fn asset_text_path(state_root: &Path, asset: &AssetView) -> Result<PathBuf> {
    let text_uri = asset
        .text_uri
        .as_deref()
        .ok_or_else(|| anyhow!("asset {} has no derived text URI", asset.asset_id))?;
    let relative = text_uri
        .strip_prefix("asset://text/")
        .ok_or_else(|| anyhow!("unexpected text asset URI {text_uri}"))?;
    Ok(state_root.join("assets").join("text").join(relative))
}

