#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn routes_default_channel_timeout_promotes_the_next_member_against_a_real_daemon()
-> Result<()> {
    let bin = cli_bin()?;
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let provider_base_url = spawn_delayed_openai_route_mock_server(
        vec![
            DelayedRouteResponse {
                delay_ms: 1200,
                body: openai_tool_call_response(
                    "emit_output",
                    json!({
                        "content": "Aurora was too slow, but still tried to answer publicly."
                    }),
                ),
            },
            DelayedRouteResponse {
                delay_ms: 0,
                body: openai_tool_call_response(
                    "emit_output",
                    json!({
                        "content": "Atlas stepped in because Aurora missed the response window."
                    }),
                ),
            },
            DelayedRouteResponse {
                delay_ms: 0,
                body: openai_text_response("ack"),
            },
            DelayedRouteResponse {
                delay_ms: 0,
                body: openai_text_response("late-ack"),
            },
        ],
        captured_requests.clone(),
    )
    .await?;

    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let routes_path = default_routes_path()?;
    let master_key = "0123456789abcdef0123456789abcdef";
    seed_default_route_auth_slots(&bin, &state_root, master_key)?;

    let openai_base_url = format!("{provider_base_url}/v1/responses");
    let (base_url, _daemon) = start_daemon_ready_with_env(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        &routes_path,
        Some("openai"),
        [
            (AUTH_STORE_MASTER_KEY_ENV, master_key),
            ("OPENAI_BASE_URL", openai_base_url.as_str()),
        ],
    )?;

    let client = Client::new();
    let _: SessionView = run_cli_json(&bin, &base_url, ["sessions", "create", "atlas-room"])?;
    let _: SessionView = run_cli_json(&bin, &base_url, ["sessions", "create", "aurora-room"])?;

    client
        .post(format!("{base_url}/v1/channels"))
        .json(&kheish_daemon::CreateChannelRequest {
            channel_id: Some("channel-timeout".to_string()),
            title: "timeout".to_string(),
            description: Some("timeout".to_string()),
            purpose: None,
            pinned_asset_ids: Vec::new(),
            created_by: None,
            members: vec![
                kheish_daemon::ChannelMemberRequest {
                    member_id: "alice".to_string(),
                    member_kind: kheish_daemon::ChannelMemberKind::HumanActor,
                    display_name_mode: None,
                    display_name: "Alice".to_string(),
                    session_id: None,
                    actor_id: Some("alice".to_string()),
                    role: Some("requester".to_string()),
                    expertise_tags: Vec::new(),
                    participation_mode: Some(kheish_daemon::ChannelParticipationMode::ManualOnly),
                    muted: Some(false),
                },
                kheish_daemon::ChannelMemberRequest {
                    member_id: "atlas-room".to_string(),
                    member_kind: kheish_daemon::ChannelMemberKind::Session,
                    display_name_mode: None,
                    display_name: "Atlas".to_string(),
                    session_id: Some("atlas-room".to_string()),
                    actor_id: None,
                    role: Some("security".to_string()),
                    expertise_tags: vec!["audit".to_string()],
                    participation_mode: None,
                    muted: Some(false),
                },
                kheish_daemon::ChannelMemberRequest {
                    member_id: "aurora-room".to_string(),
                    member_kind: kheish_daemon::ChannelMemberKind::Session,
                    display_name_mode: None,
                    display_name: "Aurora".to_string(),
                    session_id: Some("aurora-room".to_string()),
                    actor_id: None,
                    role: Some("ops".to_string()),
                    expertise_tags: vec!["linear".to_string()],
                    participation_mode: None,
                    muted: Some(false),
                },
            ],
            autonomy_policy: Some(kheish_daemon::ChannelAutonomyPolicy {
                max_parallel_public_speakers: 1,
                max_agent_replies_per_human_message: 1,
                member_cooldown_ms: 15_000,
                lease_timeout_ms: 250,
                ..Default::default()
            }),
            default_participation_mode: None,
            metadata: Value::Null,
        })
        .send()
        .await?
        .error_for_status()?;

    let posted: kheish_daemon::ChannelMessageView = client
        .post(format!("{base_url}/v1/channels/channel-timeout/messages"))
        .json(&kheish_daemon::PostChannelMessageRequest {
            sender_actor_id: "alice".to_string(),
            sender_display_name: Some("Alice".to_string()),
            sender_session_id: None,
            thread_root_message_id: None,
            reply_to_message_id: None,
            addressed_member_ids: Vec::new(),
            input_items: Vec::new(),
            content: Some("Aurora, peux-tu répondre en premier ?".to_string()),
            metadata: json!({"source": "timeout-e2e"}),
        })
        .send()
        .await?
        .error_for_status()?
        .json()
        .await?;
    assert_eq!(posted.addressed_member_ids, vec!["aurora-room".to_string()]);

    let aurora_runs = wait_for_session_run_count(&bin, &base_url, "aurora-room", 1).await?;
    let aurora_run = aurora_runs
        .last()
        .cloned()
        .ok_or_else(|| anyhow!("missing aurora timeout run"))?;
    let _ = wait_for_run_status(
        &bin,
        &base_url,
        &aurora_run.run_id,
        &[DaemonRunStatus::Running, DaemonRunStatus::Completed],
    )
    .await?;

    let atlas_runs = wait_for_session_run_count(&bin, &base_url, "atlas-room", 1).await?;
    let atlas_run = atlas_runs
        .last()
        .cloned()
        .ok_or_else(|| anyhow!("missing atlas timeout run"))?;
    let atlas_completed = wait_for_run_status(
        &bin,
        &base_url,
        &atlas_run.run_id,
        &[DaemonRunStatus::Completed],
    )
    .await?;
    assert_eq!(atlas_completed.kind, DaemonRunKind::ChannelDelivery);

    let channel_messages =
        wait_for_channel_message_count(&bin, &base_url, "channel-timeout", 2).await?;
    assert_eq!(channel_messages.len(), 2);
    assert_eq!(
        channel_messages[1].sender_session_id.as_deref(),
        Some("atlas-room")
    );
    assert!(
        channel_messages
            .iter()
            .all(|message| message.sender_session_id.as_deref() != Some("aurora-room")),
        "the timed out addressed run should not publish after Atlas takes over"
    );

    let leases: Vec<kheish_daemon::ChannelTurnLeaseView> =
        run_cli_json(&bin, &base_url, ["channels", "leases", "channel-timeout"])?;
    assert!(
        leases.is_empty(),
        "expired channel thread should settle cleanly"
    );

    let requests = wait_for_captured_route_requests(&captured_requests, 3).await?;
    assert!(
        requests.iter().any(|request| {
            request.path == "/v1/responses"
                && request
                    .body
                    .contains("Explicitly addressed members: Aurora.")
        }),
        "the original addressed run should still receive explicit prompt guidance"
    );

    Ok(())
}

