#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn mailbox_review_requests_run_against_a_real_daemon() -> Result<()> {
    let bin = cli_bin()?;
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let provider_base_url =
        spawn_openai_raw_mock_server(OPENAI_OK_RESPONSE, captured_requests.clone()).await?;

    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let routes_path = temp.path().join("routes.toml");
    write_routes_file(&routes_path, &provider_base_url, &provider_base_url)?;

    let (base_url, _daemon) =
        start_daemon_ready(&bin, &temp, &state_root, &workspace_root, &routes_path)?;

    let root: SessionView = run_cli_json(&bin, &base_url, ["sessions", "create", "review-root"])?;
    let child: SessionView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("agents"),
            OsString::from("spawn-sidechain"),
            OsString::from(root.agent_id.clone()),
            OsString::from("--session-id"),
            OsString::from("review-child"),
            OsString::from("--model"),
            OsString::from("openrouter/openai/gpt-5.4-mini"),
        ],
    )?;

    let render_path = temp.path().join("review-board.png");
    let state_path = temp.path().join("review-board.json");
    write_sample_png(&render_path)?;
    fs::write(
        &state_path,
        json!({"schema_version":1,"note":"review draft","strokes":[]}).to_string(),
    )?;
    let render_asset: AssetView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("assets"),
            OsString::from("import"),
            render_path.into_os_string(),
        ],
    )?;
    let state_asset: AssetView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("assets"),
            OsString::from("import"),
            state_path.into_os_string(),
        ],
    )?;
    let _: BoardView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("boards"),
            OsString::from("create"),
            OsString::from("Review Board"),
            OsString::from("--board-id"),
            OsString::from("review-board"),
            OsString::from("--owner-session-id"),
            OsString::from("review-root"),
        ],
    )?;
    let revision: BoardRevisionView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("boards"),
            OsString::from("create-revision"),
            OsString::from("review-board"),
            OsString::from("--render-asset-id"),
            OsString::from(render_asset.asset_id.clone()),
            OsString::from("--state-asset-id"),
            OsString::from(state_asset.asset_id.clone()),
            OsString::from("--source-session-id"),
            OsString::from("review-root"),
            OsString::from("--note"),
            OsString::from("seed reviewer board"),
        ],
    )?;

    let payload = json!({
        "type": "review_request",
        "instruction": "Review the board against the constraints.",
        "input_items": [
            { "type": "text", "text": "Review the attached board revision." },
            {
                "type": "board_reference",
                "board_id": "review-board",
                "revision_id": revision.revision_id
            }
        ]
    })
    .to_string();
    let root_agent_id = root.agent_id.clone();
    let posted: Value = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("mailboxes"),
            OsString::from("post"),
            OsString::from("--from-agent-id"),
            OsString::from(root_agent_id.clone()),
            OsString::from("--to-agent-id"),
            OsString::from(child.agent_id.clone()),
            OsString::from("--subject"),
            OsString::from("review-request"),
            OsString::from("--payload-json"),
            OsString::from(payload),
        ],
    )?;
    assert_eq!(posted["accepted"], Value::Bool(true));

    let completed = wait_for_completed_session_run(&bin, &base_url, "review-child").await?;
    assert_eq!(completed.status, DaemonRunStatus::Completed);
    assert_eq!(completed.input_attachments.len(), 1);
    assert_eq!(completed.input_attachments[0].id, render_asset.asset_id);

    let requests = wait_for_captured_requests(&captured_requests, 1).await?;
    assert!(
        requests
            .iter()
            .any(|request| request.contains("You received mailbox messages from other agents."))
    );
    assert!(
        requests
            .iter()
            .any(|request| request.contains("Review the board against the constraints."))
    );
    assert!(
        requests
            .iter()
            .any(|request| request.contains("Review the attached board revision."))
    );

    let follow_up_payload = json!({
        "type": "review_note",
        "instruction": "Store this mailbox note for explicit draining.",
        "input_items": [{ "type": "text", "text": "Mailbox-only follow-up." }]
    })
    .to_string();
    let follow_up_posted: Value = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("mailboxes"),
            OsString::from("post"),
            OsString::from("--from-agent-id"),
            OsString::from(child.agent_id.clone()),
            OsString::from("--to-agent-id"),
            OsString::from(root_agent_id.clone()),
            OsString::from("--subject"),
            OsString::from("review-request-follow-up"),
            OsString::from("--payload-json"),
            OsString::from(follow_up_payload),
        ],
    )?;
    assert_eq!(follow_up_posted["accepted"], Value::Bool(true));

    let mailbox: Value = run_cli_json(
        &bin,
        &base_url,
        ["agents", "drain-mailbox", root_agent_id.as_str()],
    )?;
    assert!(
        mailbox.is_array(),
        "drain-mailbox should return a mailbox array: {}",
        serde_json::to_string_pretty(&mailbox)?
    );

    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn routes_file_image_generation_follows_the_selected_route_on_a_real_daemon() -> Result<()> {
    let bin = cli_bin()?;
    let openrouter_requests = Arc::new(Mutex::new(Vec::new()));
    let openrouter_base_url = spawn_openai_route_mock_server(
        vec![
            openai_tool_call_response(
                "generate_image",
                json!({
                    "prompt": "Render the route-aware image.",
                    "count": 1,
                }),
            ),
            openai_text_response("ROUTE_IMAGE_GENERATE_OK"),
        ],
        vec![openai_image_response()],
        Vec::new(),
        openrouter_requests.clone(),
    )
    .await?;
    let openai_requests = Arc::new(Mutex::new(Vec::new()));
    let openai_base_url =
        spawn_openai_route_mock_server(Vec::new(), Vec::new(), Vec::new(), openai_requests.clone())
            .await?;

    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let routes_path = temp.path().join("routes.toml");
    write_routes_file(&routes_path, &openrouter_base_url, &openai_base_url)?;

    let (base_url, _daemon) =
        start_daemon_ready(&bin, &temp, &state_root, &workspace_root, &routes_path)?;

    let _: SessionView = run_cli_json(&bin, &base_url, ["sessions", "create", "demo"])?;
    let completed: RunView = run_cli_json(
        &bin,
        &base_url,
        [
            "sessions",
            "input",
            "demo",
            "Generate the route-aware image.",
            "--model",
            "openrouter/openai/gpt-5.4-mini",
            "--wait",
        ],
    )?;
    assert_eq!(completed.status, DaemonRunStatus::Completed);
    assert!(
        completed
            .outputs
            .iter()
            .any(|output| output.content.contains("ROUTE_IMAGE_GENERATE_OK"))
    );

    let requests = wait_for_captured_route_requests(&openrouter_requests, 3).await?;
    assert_eq!(
        requests
            .iter()
            .filter(|request| request.path == "/v1/responses")
            .count(),
        2
    );
    let image_request = requests
        .iter()
        .find(|request| request.path == "/v1/images/generations")
        .ok_or_else(|| anyhow!("missing image generation request on the openrouter route"))?;
    assert!(image_request.body.contains("\"model\":\"gpt-image-1.5\""));
    assert!(
        openai_requests.lock().is_empty(),
        "default openai route unexpectedly received provider traffic"
    );

    Ok(())
}

