#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn external_connector_round_trip_and_idempotency_survive_restart_on_a_real_daemon()
-> Result<()> {
    let bin = cli_bin()?;
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let provider_base_url =
        spawn_openai_raw_mock_server(OPENAI_OK_RESPONSE, captured_requests.clone()).await?;
    let sidecar = FakeExternalSidecar::start("external-secret").await?;

    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let routes_path = default_routes_path()?;
    let master_key = "0123456789abcdef0123456789abcdef";
    seed_default_route_auth_slots(&bin, &state_root, master_key)?;
    let openai_base_url = format!("{provider_base_url}/v1/responses");

    let (base_url, mut daemon) = start_daemon_ready_with_env(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        &routes_path,
        Some("openai"),
        [
            (AUTH_STORE_MASTER_KEY_ENV, master_key),
            ("OPENAI_BASE_URL", openai_base_url.as_str()),
        ],
    )?;

    let connector_payload = json!({
        "platform": "discord",
        "mode": "remote_http",
        "base_url": sidecar.base_url,
        "allow_private_network": true,
        "shared_token": { "value": "external-secret" },
        "include_self_output": true,
        "session_policy": {
            "create_if_missing": true
        },
    });
    let connector: ConnectorView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("connectors"),
            OsString::from("put-external"),
            OsString::from("discord-main"),
            OsString::from("--json"),
            OsString::from(connector_payload.to_string()),
        ],
    )?;
    match connector {
        ConnectorView::External(view) => {
            assert_eq!(view.name, "discord-main");
            assert_eq!(view.platform, "discord");
            assert_eq!(view.mode, kheish_daemon::ExternalConnectorMode::RemoteHttp);
            assert_eq!(view.shared_token.source.as_deref(), Some("secret_ref"));
        }
        other => bail!("unexpected connector view: {other:?}"),
    }

    let client = Client::new();
    let first = client
        .post(format!(
            "{base_url}/v1/connectors/external/discord-main/events"
        ))
        .bearer_auth("external-secret")
        .json(&json!({
            "protocol_version": 1,
            "instance_id": "sidecar-1",
            "event_id": "evt-1",
            "actor_id": "user-1",
            "source_kind": "message",
            "thread": {
                "path": ["guild-1", "channel-2", "thread-3"]
            },
            "content": "hello from external connector",
            "reply_route": "route-1"
        }))
        .send()
        .await?
        .error_for_status()?
        .json::<Value>()
        .await?;
    assert_eq!(
        first.get("status").and_then(Value::as_str),
        Some("accepted")
    );
    let first_run_id = first
        .get("run_id")
        .and_then(Value::as_str)
        .ok_or_else(|| anyhow!("missing run_id in external ingress response"))?
        .to_string();
    let first_session_id = first
        .get("session_id")
        .and_then(Value::as_str)
        .ok_or_else(|| anyhow!("missing session_id in external ingress response"))?
        .to_string();

    let first_run: RunView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("runs"),
            OsString::from("wait"),
            OsString::from(first_run_id.clone()),
        ],
    )?;
    let first_fingerprint = first_run
        .input_metadata
        .as_ref()
        .and_then(|metadata| metadata.get("external_event_fingerprint"))
        .and_then(Value::as_str)
        .ok_or_else(|| anyhow!("missing external_event_fingerprint"))?;
    let receipt_shard_path = resolve_storage_path_for_read(
        &state_root.join("connector-ingress").join("external"),
        "discord-main",
        "json",
    );
    let receipt_shard_text = fs::read_to_string(&receipt_shard_path)
        .with_context(|| format!("failed to read {}", receipt_shard_path.display()))?;
    assert!(
        !receipt_shard_text.contains("\"evt-1\""),
        "external receipt shard should store hashed event ids, not raw event ids: {receipt_shard_text}"
    );
    let receipt_shard: Value = serde_json::from_str(&receipt_shard_text)?;
    let event_digest = kheish_codec::digest_text("evt-1");
    let receipt_key = event_digest
        .get(..32)
        .ok_or_else(|| anyhow!("short external event digest"))?;
    let receipt_fingerprint = receipt_shard
        .get("receipts")
        .and_then(Value::as_object)
        .and_then(|receipts| receipts.get(receipt_key))
        .and_then(|receipt| receipt.get("fingerprint"))
        .and_then(Value::as_str);
    assert_eq!(
        receipt_fingerprint,
        Some(first_fingerprint),
        "external receipt shard should persist the payload fingerprint"
    );
    let deliveries = sidecar.wait_for_deliveries(1).await?;
    assert_eq!(
        deliveries[0].get("content").and_then(Value::as_str),
        Some("ok")
    );
    assert_eq!(
        deliveries[0].get("reply_route").and_then(Value::as_str),
        Some("route-1")
    );
    assert!(
        deliveries[0]
            .get("delivery_id")
            .and_then(Value::as_str)
            .is_some(),
        "external deliveries should expose a stable delivery_id"
    );
    let provider_requests = wait_for_captured_requests(&captured_requests, 1).await?;
    assert_eq!(provider_requests.len(), 1);

    let connector_payload_with_new_fixed_session = json!({
        "platform": "discord",
        "mode": "remote_http",
        "base_url": sidecar.base_url,
        "allow_private_network": true,
        "shared_token": { "value": "external-secret" },
        "include_self_output": true,
        "fixed_session_id": "external-fixed-after-first-run",
        "session_policy": {
            "create_if_missing": true
        },
    });
    let _: ConnectorView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("connectors"),
            OsString::from("put-external"),
            OsString::from("discord-main"),
            OsString::from("--json"),
            OsString::from(connector_payload_with_new_fixed_session.to_string()),
        ],
    )?;

    let duplicate = client
        .post(format!(
            "{base_url}/v1/connectors/external/discord-main/events"
        ))
        .bearer_auth("external-secret")
        .json(&json!({
            "protocol_version": 1,
            "instance_id": "sidecar-1",
            "event_id": "evt-1",
            "actor_id": "user-1",
            "source_kind": "message",
            "thread": {
                "path": ["guild-1", "channel-2", "thread-3"]
            },
            "content": "hello from external connector",
            "reply_route": "route-1"
        }))
        .send()
        .await?
        .error_for_status()?
        .json::<Value>()
        .await?;
    assert_eq!(
        duplicate.get("status").and_then(Value::as_str),
        Some("duplicate")
    );
    assert_eq!(
        duplicate.get("run_id").and_then(Value::as_str),
        Some(first_run_id.as_str())
    );
    assert_eq!(
        duplicate.get("session_id").and_then(Value::as_str),
        Some(first_session_id.as_str())
    );
    assert_eq!(
        wait_for_captured_requests(&captured_requests, 1)
            .await?
            .len(),
        1
    );
    let conflicting = client
        .post(format!(
            "{base_url}/v1/connectors/external/discord-main/events"
        ))
        .bearer_auth("external-secret")
        .json(&json!({
            "protocol_version": 1,
            "instance_id": "sidecar-1",
            "event_id": "evt-1",
            "actor_id": "user-1",
            "source_kind": "message",
            "thread": {
                "path": ["guild-1", "channel-2", "thread-3"]
            },
            "content": "mutated payload should be rejected",
            "reply_route": "route-1"
        }))
        .send()
        .await?
        .error_for_status()?
        .json::<Value>()
        .await?;
    assert_eq!(
        conflicting.get("status").and_then(Value::as_str),
        Some("rejected")
    );
    assert_eq!(
        conflicting.get("run_id").and_then(Value::as_str),
        Some(first_run_id.as_str())
    );
    assert_eq!(
        conflicting.get("session_id").and_then(Value::as_str),
        Some(first_session_id.as_str())
    );
    assert_eq!(
        wait_for_captured_requests(&captured_requests, 1)
            .await?
            .len(),
        1
    );
    let metrics = client
        .get(format!("{base_url}/v1/runtime/connectors/external/metrics"))
        .send()
        .await?
        .error_for_status()?
        .text()
        .await?;
    assert!(metrics.contains(
        "kheish_external_connector_ingress_total{connector=\"discord-main\",status=\"accepted\"} 1"
    ));
    assert!(metrics.contains(
        "kheish_external_connector_ingress_total{connector=\"discord-main\",status=\"duplicate\"} 1"
    ));
    assert!(metrics.contains(
        "kheish_external_connector_ingress_total{connector=\"discord-main\",status=\"rejected\"} 1"
    ));

    stop_daemon(&mut daemon)?;
    let (base_url, _daemon) = start_daemon_ready_with_env(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        &routes_path,
        Some("openai"),
        [
            (AUTH_STORE_MASTER_KEY_ENV, master_key),
            ("OPENAI_BASE_URL", openai_base_url.as_str()),
        ],
    )?;
    let restored = client
        .post(format!(
            "{base_url}/v1/connectors/external/discord-main/events"
        ))
        .bearer_auth("external-secret")
        .json(&json!({
            "protocol_version": 1,
            "instance_id": "sidecar-1",
            "event_id": "evt-1",
            "actor_id": "user-1",
            "source_kind": "message",
            "thread": {
                "path": ["guild-1", "channel-2", "thread-3"]
            },
            "content": "hello from external connector",
            "reply_route": "route-1"
        }))
        .send()
        .await?
        .error_for_status()?
        .json::<Value>()
        .await?;
    assert_eq!(
        restored.get("status").and_then(Value::as_str),
        Some("duplicate")
    );
    assert_eq!(
        restored.get("run_id").and_then(Value::as_str),
        Some(first_run_id.as_str())
    );
    assert_eq!(
        restored.get("session_id").and_then(Value::as_str),
        Some(first_session_id.as_str())
    );
    assert_eq!(
        wait_for_captured_requests(&captured_requests, 1)
            .await?
            .len(),
        1
    );
    let metrics = client
        .get(format!("{base_url}/v1/runtime/connectors/external/metrics"))
        .send()
        .await?
        .error_for_status()?
        .text()
        .await?;
    assert!(metrics.contains(
        "kheish_external_connector_ingress_total{connector=\"discord-main\",status=\"accepted\"} 0"
    ));
    assert!(metrics.contains(
        "kheish_external_connector_ingress_total{connector=\"discord-main\",status=\"duplicate\"} 1"
    ));
    assert!(metrics.contains(
        "kheish_external_connector_ingress_total{connector=\"discord-main\",status=\"rejected\"} 0"
    ));
    assert_eq!(sidecar.wait_for_deliveries(1).await?.len(), 1);
    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn external_connector_delivery_retry_survives_restart_on_a_real_daemon() -> Result<()> {
    let bin = cli_bin()?;
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let provider_base_url =
        spawn_openai_raw_mock_server(OPENAI_OK_RESPONSE, captured_requests.clone()).await?;
    let sidecar = FakeExternalSidecar::start("external-secret").await?;
    sidecar.set_retryable_failures(1);

    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let routes_path = default_routes_path()?;
    let master_key = "0123456789abcdef0123456789abcdef";
    seed_default_route_auth_slots(&bin, &state_root, master_key)?;
    let openai_base_url = format!("{provider_base_url}/v1/responses");

    let (base_url, mut daemon) = start_daemon_ready_with_env(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        &routes_path,
        Some("openai"),
        [
            (AUTH_STORE_MASTER_KEY_ENV, master_key),
            ("OPENAI_BASE_URL", openai_base_url.as_str()),
            ("KHEISH_DELIVERY_INITIAL_RETRY_MS", "1500"),
            ("KHEISH_DELIVERY_MAX_RETRY_MS", "1500"),
            ("KHEISH_DELIVERY_MAX_ATTEMPTS", "4"),
        ],
    )?;

    let connector_payload = json!({
        "platform": "discord",
        "mode": "remote_http",
        "base_url": sidecar.base_url,
        "allow_private_network": true,
        "shared_token": { "value": "external-secret" },
        "include_self_output": true,
        "session_policy": {
            "create_if_missing": true
        },
    });
    let _: ConnectorView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("connectors"),
            OsString::from("put-external"),
            OsString::from("discord-retry"),
            OsString::from("--json"),
            OsString::from(connector_payload.to_string()),
        ],
    )?;

    let client = Client::new();
    let first = client
        .post(format!(
            "{base_url}/v1/connectors/external/discord-retry/events"
        ))
        .bearer_auth("external-secret")
        .json(&json!({
            "protocol_version": 1,
            "instance_id": "sidecar-1",
            "event_id": "evt-retry-1",
            "actor_id": "user-1",
            "source_kind": "message",
            "thread": {
                "path": ["guild-1", "channel-2", "thread-4"]
            },
            "content": "retry me",
            "reply_route": "retry-route-1"
        }))
        .send()
        .await?
        .error_for_status()?
        .json::<Value>()
        .await?;
    let run_id = first
        .get("run_id")
        .and_then(Value::as_str)
        .ok_or_else(|| anyhow!("missing run_id"))?
        .to_string();
    let _: RunView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("runs"),
            OsString::from("wait"),
            OsString::from(run_id.clone()),
        ],
    )?;

    let first_attempts = sidecar.wait_for_deliveries(1).await?;
    let first_delivery_id = first_attempts[0]
        .get("delivery_id")
        .and_then(Value::as_str)
        .ok_or_else(|| anyhow!("missing delivery_id"))?
        .to_string();
    assert_eq!(
        first_attempts[0].get("attempt").and_then(Value::as_u64),
        Some(1)
    );
    assert_eq!(
        wait_for_captured_requests(&captured_requests, 1)
            .await?
            .len(),
        1
    );

    stop_daemon(&mut daemon)?;
    sidecar.set_retryable_failures(0);
    let (base_url, _daemon) = start_daemon_ready_with_env(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        &routes_path,
        Some("openai"),
        [
            (AUTH_STORE_MASTER_KEY_ENV, master_key),
            ("OPENAI_BASE_URL", openai_base_url.as_str()),
            ("KHEISH_DELIVERY_INITIAL_RETRY_MS", "1500"),
            ("KHEISH_DELIVERY_MAX_RETRY_MS", "1500"),
            ("KHEISH_DELIVERY_MAX_ATTEMPTS", "4"),
        ],
    )?;

    let second_attempts = sidecar.wait_for_deliveries(2).await?;
    assert_eq!(
        second_attempts[1]
            .get("delivery_id")
            .and_then(Value::as_str),
        Some(first_delivery_id.as_str())
    );
    assert_eq!(
        second_attempts[1].get("attempt").and_then(Value::as_u64),
        Some(2)
    );
    assert_eq!(
        wait_for_captured_requests(&captured_requests, 1)
            .await?
            .len(),
        1
    );
    let completed: RunView = run_cli_json(&bin, &base_url, ["runs", "get", run_id.as_str()])?;
    assert_eq!(completed.status, DaemonRunStatus::Completed);
    let audit_records: Vec<ExternalActionAuditRecord> = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("runs"),
            OsString::from("external-actions"),
            OsString::from(run_id.clone()),
        ],
    )?;
    let connector_delivery_records = audit_records
        .iter()
        .filter(|record| record.kind == "connector_delivery")
        .collect::<Vec<_>>();
    assert!(
        connector_delivery_records.len() >= 4,
        "expected request/response records for both connector delivery attempts: {audit_records:#?}"
    );
    assert!(connector_delivery_records.iter().all(|record| {
        record.run_id.as_deref() == Some(run_id.as_str())
            && record.target.starts_with("external:discord-retry:/deliver")
            && record.signature_alg == "ed25519"
    }));
    assert!(connector_delivery_records.iter().any(|record| {
        record.phase == "response" && record.outcome.as_deref() == Some("retryable_error")
    }));
    assert!(connector_delivery_records.iter().any(|record| {
        record.phase == "response" && record.outcome.as_deref() == Some("committed")
    }));
    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn external_connector_delivery_target_circuit_survives_restart_on_a_real_daemon() -> Result<()>
{
    let bin = cli_bin()?;
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let provider_base_url =
        spawn_openai_raw_mock_server(OPENAI_OK_RESPONSE, captured_requests.clone()).await?;
    let sidecar = FakeExternalSidecar::start("external-secret").await?;
    sidecar.set_retryable_failures(usize::MAX);

    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let routes_path = default_routes_path()?;
    let master_key = "0123456789abcdef0123456789abcdef";
    seed_default_route_auth_slots(&bin, &state_root, master_key)?;
    let openai_base_url = format!("{provider_base_url}/v1/responses");

    let (base_url, mut daemon) = start_daemon_ready_with_env(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        &routes_path,
        Some("openai"),
        [
            (AUTH_STORE_MASTER_KEY_ENV, master_key),
            ("OPENAI_BASE_URL", openai_base_url.as_str()),
            ("KHEISH_DELIVERY_INITIAL_RETRY_MS", "300"),
            ("KHEISH_DELIVERY_MAX_RETRY_MS", "300"),
            ("KHEISH_DELIVERY_MAX_ATTEMPTS", "4"),
            ("KHEISH_DELIVERY_CIRCUIT_FAILURE_THRESHOLD", "1"),
            ("KHEISH_DELIVERY_CIRCUIT_COOLDOWN_MS", "60000"),
        ],
    )?;

    let connector_payload = json!({
        "platform": "discord",
        "mode": "remote_http",
        "base_url": sidecar.base_url,
        "allow_private_network": true,
        "shared_token": { "value": "external-secret" },
        "include_self_output": true,
        "session_policy": {
            "create_if_missing": true
        },
    });
    let _: ConnectorView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("connectors"),
            OsString::from("put-external"),
            OsString::from("discord-circuit"),
            OsString::from("--json"),
            OsString::from(connector_payload.to_string()),
        ],
    )?;

    let client = Client::new();
    let first = client
        .post(format!(
            "{base_url}/v1/connectors/external/discord-circuit/events"
        ))
        .bearer_auth("external-secret")
        .json(&json!({
            "protocol_version": 1,
            "instance_id": "sidecar-1",
            "event_id": "evt-circuit-1",
            "actor_id": "user-1",
            "source_kind": "message",
            "thread": {
                "path": ["guild-1", "channel-2", "thread-circuit"]
            },
            "content": "open delivery circuit",
            "reply_route": "circuit-route-secret-1"
        }))
        .send()
        .await?
        .error_for_status()?
        .json::<Value>()
        .await?;
    let run_id = first
        .get("run_id")
        .and_then(Value::as_str)
        .ok_or_else(|| anyhow!("missing run_id"))?
        .to_string();
    let _: RunView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("runs"),
            OsString::from("wait"),
            OsString::from(run_id.clone()),
        ],
    )?;
    let first_attempts = sidecar.wait_for_deliveries(1).await?;
    assert_eq!(
        first_attempts[0].get("attempt").and_then(Value::as_u64),
        Some(1)
    );
    assert_eq!(
        wait_for_captured_requests(&captured_requests, 1)
            .await?
            .len(),
        1
    );

    let deadline = Instant::now() + Duration::from_secs(10);
    let opened_status = loop {
        let status: Value = run_cli_json(&bin, &base_url, ["status"])?;
        let has_open_circuit = status
            .pointer("/delivery/open_circuit_target_count")
            .and_then(Value::as_u64)
            == Some(1);
        let health_codes = status
            .pointer("/health/warnings")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(|warning| warning.get("code").and_then(Value::as_str))
            .collect::<Vec<_>>();
        if has_open_circuit && health_codes.contains(&"delivery_target_circuit_open") {
            break status;
        }
        if Instant::now() >= deadline {
            bail!("timed out waiting for delivery target circuit health warning: {status:#}");
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    };
    assert_eq!(
        opened_status
            .pointer("/delivery/throttled_target_count")
            .and_then(Value::as_u64),
        Some(1)
    );
    assert_eq!(
        opened_status
            .pointer("/delivery/dispatchable")
            .and_then(Value::as_u64),
        Some(0)
    );
    assert!(
        opened_status
            .pointer("/delivery/next_target_available_at_ms")
            .and_then(Value::as_u64)
            .is_some()
    );
    tokio::time::sleep(Duration::from_millis(800)).await;
    assert_eq!(
        sidecar.delivery_count(),
        1,
        "open target circuit should suppress retry attempts"
    );

    let backpressure_path = state_root.join("daemon-deliveries.d/target-backpressure.json");
    let backpressure = fs::read_to_string(&backpressure_path)
        .with_context(|| format!("failed to read {}", backpressure_path.display()))?;
    assert!(backpressure.contains("address_sha256"));
    assert!(!backpressure.contains("circuit-route-secret-1"));
    assert!(!backpressure.contains(&sidecar.base_url));
    assert!(!backpressure.contains("external-secret"));

    stop_daemon(&mut daemon)?;
    let (base_url, _daemon) = start_daemon_ready_with_env(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        &routes_path,
        Some("openai"),
        [
            (AUTH_STORE_MASTER_KEY_ENV, master_key),
            ("OPENAI_BASE_URL", openai_base_url.as_str()),
            ("KHEISH_DELIVERY_INITIAL_RETRY_MS", "300"),
            ("KHEISH_DELIVERY_MAX_RETRY_MS", "300"),
            ("KHEISH_DELIVERY_MAX_ATTEMPTS", "4"),
            ("KHEISH_DELIVERY_CIRCUIT_FAILURE_THRESHOLD", "1"),
            ("KHEISH_DELIVERY_CIRCUIT_COOLDOWN_MS", "60000"),
        ],
    )?;
    let restarted_status: Value = run_cli_json(&bin, &base_url, ["status"])?;
    assert_eq!(
        restarted_status
            .pointer("/delivery/open_circuit_target_count")
            .and_then(Value::as_u64),
        Some(1),
        "target circuit state should be durable across daemon restart: {restarted_status:#}"
    );
    tokio::time::sleep(Duration::from_millis(800)).await;
    assert_eq!(
        sidecar.delivery_count(),
        1,
        "restarted daemon should honor persisted target circuit before retrying"
    );

    let delivery_views: Vec<DeliveryView> = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("deliveries"),
            OsString::from("list"),
            OsString::from("--run-id"),
            OsString::from(run_id.clone()),
        ],
    )?;
    let target = delivery_views
        .iter()
        .find(|delivery| delivery.status == DeliveryStatus::Retrying)
        .map(|delivery| delivery.target.clone())
        .ok_or_else(|| anyhow!("missing retrying delivery target: {delivery_views:#?}"))?;
    assert!(target.starts_with("external:address_sha256:"));
    assert!(!target.contains("circuit-route-secret-1"));
    let dry_run: DeliveryBackpressureResetResponse = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("deliveries"),
            OsString::from("reset-backpressure"),
            OsString::from("--target"),
            OsString::from(target.clone()),
            OsString::from("--dry-run"),
        ],
    )?;
    assert!(dry_run.dry_run);
    assert_eq!(dry_run.matched, 1);
    assert_eq!(dry_run.removed, 0);
    assert_eq!(dry_run.targets, vec![target.clone()]);
    assert_eq!(sidecar.delivery_count(), 1);

    let reset: DeliveryBackpressureResetResponse = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("deliveries"),
            OsString::from("reset-backpressure"),
            OsString::from("--target"),
            OsString::from(target),
        ],
    )?;
    assert!(!reset.dry_run);
    assert_eq!(reset.matched, 1);
    assert_eq!(reset.removed, 1);
    let reset_attempts = sidecar.wait_for_deliveries(2).await?;
    assert_eq!(
        reset_attempts[1].get("attempt").and_then(Value::as_u64),
        Some(2),
        "operator backpressure reset should wake the worker for the due retry"
    );
    Ok(())
}

