#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn external_child_process_connector_delivers_on_a_real_daemon() -> Result<()> {
    let bin = cli_bin()?;
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let provider_base_url =
        spawn_openai_raw_mock_server(OPENAI_OK_RESPONSE, captured_requests.clone()).await?;

    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let routes_path = default_routes_path()?;
    let master_key = "0123456789abcdef0123456789abcdef";
    seed_default_route_auth_slots(&bin, &state_root, master_key)?;
    let openai_base_url = format!("{provider_base_url}/v1/responses");
    let bind = reserve_bind_address()?;
    let mut bind_parts = bind.split(':');
    let host = bind_parts
        .next()
        .ok_or_else(|| anyhow!("missing bind host"))?
        .to_string();
    let port = bind_parts
        .next()
        .ok_or_else(|| anyhow!("missing bind port"))?
        .to_string();
    let script_path = temp.path().join("external-sidecar.py");
    let log_path = temp.path().join("external-sidecar-deliveries.jsonl");
    let pid_path = temp.path().join("external-sidecar.pid");
    let env_path = temp.path().join("external-sidecar-env.json");
    fs::write(
        &script_path,
        r#"import json
import os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

TOKEN = os.environ["KHEISH_EXTERNAL_CONNECTOR_SHARED_TOKEN"]
HOST = os.environ["SIDECAR_HOST"]
PORT = int(os.environ["SIDECAR_PORT"])
LOG_PATH = os.environ["SIDECAR_LOG_PATH"]
PID_PATH = os.environ["SIDECAR_PID_PATH"]
ENV_PATH = os.environ["SIDECAR_ENV_PATH"]
INSTANCE_ID = os.environ.get("SIDECAR_INSTANCE_ID", "child-sidecar-1")

with open(PID_PATH, "w", encoding="utf-8") as handle:
    handle.write(str(os.getpid()))
with open(ENV_PATH, "w", encoding="utf-8") as handle:
    json.dump(
        {
            "daemon_base_url": os.environ.get("KHEISH_EXTERNAL_CONNECTOR_DAEMON_BASE_URL"),
            "shared_token_present": bool(os.environ.get("KHEISH_EXTERNAL_CONNECTOR_SHARED_TOKEN")),
            "openai_base_url": os.environ.get("OPENAI_BASE_URL"),
            "openai_api_key": os.environ.get("OPENAI_API_KEY"),
        },
        handle,
    )

class Handler(BaseHTTPRequestHandler):
    def _authorized(self):
        return self.headers.get("Authorization") == f"Bearer {TOKEN}"

    def _json(self, status, payload):
        body = json.dumps(payload).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        if not self._authorized():
            self._json(401, {"error": "unauthorized"})
            return
        if self.path == "/manifest":
            self._json(200, {"protocol_version": 1, "instance_id": INSTANCE_ID})
            return
        if self.path == "/health":
            self._json(200, {"protocol_version": 1, "instance_id": INSTANCE_ID, "status": "ready"})
            return
        self._json(404, {"error": "not_found"})

    def do_POST(self):
        if not self._authorized():
            self._json(401, {"error": "unauthorized"})
            return
        length = int(self.headers.get("Content-Length", "0"))
        body = self.rfile.read(length).decode("utf-8")
        if self.path == "/deliver":
            with open(LOG_PATH, "a", encoding="utf-8") as handle:
                handle.write(body + "\n")
            self._json(200, {"status": "committed"})
            return
        self._json(404, {"error": "not_found"})

    def log_message(self, format, *args):
        return

ThreadingHTTPServer((HOST, PORT), Handler).serve_forever()
"#,
    )?;

    let (base_url, _daemon) = start_daemon_ready_with_env(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        &routes_path,
        Some("openai"),
        [
            (AUTH_STORE_MASTER_KEY_ENV, master_key),
            ("OPENAI_BASE_URL", openai_base_url.as_str()),
            ("OPENAI_API_KEY", "should-not-leak-to-child-process"),
        ],
    )?;

    let connector_payload = json!({
        "platform": "discord",
        "mode": "child_process",
        "base_url": format!("http://{bind}"),
        "shared_token": { "value": "child-secret" },
        "include_self_output": true,
        "child_process": {
            "command": "python3",
            "args": [script_path],
            "env": {
                "SIDECAR_HOST": host,
                "SIDECAR_PORT": port,
                "SIDECAR_LOG_PATH": log_path,
                "SIDECAR_PID_PATH": pid_path,
                "SIDECAR_ENV_PATH": env_path,
            }
        }
    });
    let _: ConnectorView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("connectors"),
            OsString::from("put-external"),
            OsString::from("discord-child"),
            OsString::from("--json"),
            OsString::from(connector_payload.to_string()),
        ],
    )?;
    wait_for_external_sidecar_health(&format!("http://{bind}"), "child-secret").await?;
    let env_snapshot: Value = serde_json::from_str(&wait_for_file_text(&env_path).await?)?;
    assert_eq!(
        env_snapshot.get("daemon_base_url").and_then(Value::as_str),
        Some(base_url.as_str())
    );
    assert_eq!(
        env_snapshot
            .get("shared_token_present")
            .and_then(Value::as_bool),
        Some(true)
    );
    assert_eq!(env_snapshot.get("openai_base_url"), Some(&Value::Null));
    assert_eq!(env_snapshot.get("openai_api_key"), Some(&Value::Null));
    let first_pid = wait_for_file_text(&pid_path).await?;
    std::process::Command::new("kill")
        .arg("-9")
        .arg(&first_pid)
        .status()
        .context("failed to kill external child sidecar")?;
    wait_for_external_sidecar_health(&format!("http://{bind}"), "child-secret").await?;
    let restarted_pid = wait_for_changed_file_text(&pid_path, &first_pid).await?;
    assert_ne!(restarted_pid, first_pid);

    let _: SessionView = run_cli_json(&bin, &base_url, ["sessions", "create", "external-child"])?;
    let reply_targets_payload = json!({
        "reply_targets": [{
            "type": "external",
            "connector": "discord-child",
            "route": "room-1"
        }]
    });
    let _: SessionView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("sessions"),
            OsString::from("set-reply-targets"),
            OsString::from("external-child"),
            OsString::from("--reply-targets-json"),
            OsString::from(reply_targets_payload.to_string()),
        ],
    )?;

    let run: RunView = run_cli_json(
        &bin,
        &base_url,
        [
            "sessions",
            "input",
            "external-child",
            "Send one answer through the external child-process connector.",
            "--model",
            "openai/gpt-5.4",
        ],
    )?;
    let _: RunView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("runs"),
            OsString::from("wait"),
            OsString::from(run.run_id.clone()),
        ],
    )?;
    let deliveries = wait_for_jsonl_records(&log_path, 1).await?;
    assert_eq!(
        deliveries[0].get("content").and_then(Value::as_str),
        Some("ok")
    );
    assert_eq!(
        deliveries[0].get("reply_route").and_then(Value::as_str),
        Some("room-1")
    );
    assert!(
        deliveries[0]
            .get("delivery_id")
            .and_then(Value::as_str)
            .is_some(),
        "child-process sidecar deliveries should expose a delivery_id"
    );
    assert_eq!(
        wait_for_captured_requests(&captured_requests, 1)
            .await?
            .len(),
        1
    );

    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn external_child_process_spawn_failure_backs_off_on_a_real_daemon() -> Result<()> {
    let bin = cli_bin()?;
    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let routes_path = default_routes_path()?;
    let master_key = "0123456789abcdef0123456789abcdef";
    seed_default_route_auth_slots(&bin, &state_root, master_key)?;
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let openai_base_url =
        spawn_openai_raw_mock_server(OPENAI_OK_RESPONSE, captured_requests).await?;

    let (base_url, _daemon) = start_daemon_ready_with_env(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        &routes_path,
        Some("openai"),
        [
            (AUTH_STORE_MASTER_KEY_ENV, master_key),
            ("OPENAI_BASE_URL", openai_base_url.as_str()),
        ],
    )?;
    let bind = reserve_bind_address()?;
    let connector_payload = json!({
        "platform": "discord",
        "mode": "child_process",
        "base_url": format!("http://{bind}"),
        "shared_token": { "value": "bad-child-secret" },
        "child_process": {
            "command": "__kheish_missing_external_child_process__"
        }
    });
    let _: ConnectorView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("connectors"),
            OsString::from("put-external"),
            OsString::from("discord-bad-child"),
            OsString::from("--json"),
            OsString::from(connector_payload.to_string()),
        ],
    )?;

    let client = Client::new();
    let first_restart_count =
        wait_for_external_child_restart_count(&client, &base_url, "discord-bad-child", 1).await?;
    assert_eq!(first_restart_count, 1);
    tokio::time::sleep(Duration::from_millis(350)).await;
    let metrics = client
        .get(format!("{base_url}/v1/runtime/connectors/external/metrics"))
        .send()
        .await?
        .error_for_status()?
        .text()
        .await?;
    assert_eq!(
        external_child_restart_count(&metrics, "discord-bad-child"),
        Some(1),
        "spawn failures should be governed by restart backoff, not a tight supervisor loop: {metrics}"
    );
    Ok(())
}

async fn wait_for_external_child_restart_count(
    client: &Client,
    base_url: &str,
    connector: &str,
    minimum: u64,
) -> Result<u64> {
    let deadline = Instant::now() + Duration::from_secs(5);
    loop {
        let metrics = client
            .get(format!("{base_url}/v1/runtime/connectors/external/metrics"))
            .send()
            .await?
            .error_for_status()?
            .text()
            .await?;
        if let Some(count) = external_child_restart_count(&metrics, connector)
            && count >= minimum
        {
            return Ok(count);
        }
        if Instant::now() >= deadline {
            bail!("timed out waiting for external child restart metric for {connector}: {metrics}");
        }
        tokio::time::sleep(Duration::from_millis(50)).await;
    }
}

fn external_child_restart_count(metrics: &str, connector: &str) -> Option<u64> {
    let prefix =
        format!("kheish_external_connector_child_restarts_total{{connector=\"{connector}\"}} ");
    metrics
        .lines()
        .find_map(|line| line.strip_prefix(&prefix)?.trim().parse().ok())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn connector_ingress_session_policy_and_idempotency_survive_restart_on_a_real_daemon()
-> Result<()> {
    let bin = cli_bin()?;
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let provider_base_url =
        spawn_openai_raw_mock_server(OPENAI_OK_RESPONSE, captured_requests.clone()).await?;

    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let routes_path = default_routes_path()?;
    let master_key = "0123456789abcdef0123456789abcdef";
    seed_default_route_auth_slots(&bin, &state_root, master_key)?;
    let openai_base_url = format!("{provider_base_url}/v1/responses");

    let (base_url, mut daemon) = start_daemon_ready_with_env(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        &routes_path,
        Some("openai"),
        [
            (AUTH_STORE_MASTER_KEY_ENV, master_key),
            ("OPENAI_BASE_URL", openai_base_url.as_str()),
        ],
    )?;

    let _: PersonaView = run_cli_json(
        &bin,
        &base_url,
        [
            "personas",
            "create",
            "Inbound Reviewer",
            "--persona-id",
            "reviewer.persona",
            "--soul",
            "Review inbound connector requests before answering.",
        ],
    )?;

    let connector_payload = json!({
        "actor_id": "http-webhook",
        "bearer_token": { "value": "http-secret" },
        "session_policy": {
            "create_if_missing": true,
            "persona_id": "reviewer.persona",
            "capability_scope": {
                "skill_deny": ["github-auth"]
            }
        }
    });
    let connector: ConnectorView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("connectors"),
            OsString::from("put-http"),
            OsString::from("ingress"),
            OsString::from("--json"),
            OsString::from(connector_payload.to_string()),
        ],
    )?;
    match connector {
        ConnectorView::Http(view) => {
            assert!(view.bearer_token.configured);
            assert!(view.session_policy.create_if_missing);
            assert_eq!(
                view.session_policy.persona_id.as_deref(),
                Some("reviewer.persona")
            );
            assert_eq!(
                view.session_policy.capability_scope.skill_deny,
                vec!["github-auth".to_string()]
            );
        }
        other => bail!("unexpected connector view: {other:?}"),
    }

    let client = Client::new();
    let first_run = client
        .post(format!("{base_url}/v1/connectors/http/ingress"))
        .bearer_auth("http-secret")
        .json(&json!({
            "session_id": "connector-session-policy",
            "content": "hello from ingress",
            "idempotency_key": "req-1"
        }))
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    let completed: RunView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("runs"),
            OsString::from("wait"),
            OsString::from(first_run.run_id.clone()),
        ],
    )?;
    assert_eq!(completed.status, DaemonRunStatus::Completed);
    let session: SessionView = run_cli_json(
        &bin,
        &base_url,
        ["sessions", "get", "connector-session-policy"],
    )?;
    assert_eq!(
        session
            .persona
            .as_ref()
            .map(|persona| persona.persona_id.as_str()),
        Some("reviewer.persona")
    );
    assert_eq!(
        session.capability_scope.skill_deny,
        vec!["github-auth".to_string()]
    );
    let shard_dir = state_root.join("connector-ingress/http");
    let shard_files = fs::read_dir(&shard_dir)?
        .map(|entry| entry.map(|entry| entry.path()))
        .collect::<std::result::Result<Vec<_>, _>>()?;
    assert!(
        !shard_files.is_empty(),
        "connector ingress shard files should be persisted under {}",
        shard_dir.display()
    );

    let duplicate_run = client
        .post(format!("{base_url}/v1/connectors/http/ingress"))
        .bearer_auth("http-secret")
        .json(&json!({
            "session_id": "connector-session-policy",
            "content": "hello from ingress",
            "idempotency_key": "req-1"
        }))
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    assert_eq!(duplicate_run.run_id, first_run.run_id);
    let requests = wait_for_captured_requests(&captured_requests, 1).await?;
    assert_eq!(
        requests.len(),
        1,
        "duplicate ingress should not trigger a second provider request before restart"
    );

    stop_daemon(&mut daemon)?;
    let (base_url, _daemon) = start_daemon_ready_with_env(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        &routes_path,
        Some("openai"),
        [
            (AUTH_STORE_MASTER_KEY_ENV, master_key),
            ("OPENAI_BASE_URL", openai_base_url.as_str()),
        ],
    )?;

    let restored_run = client
        .post(format!("{base_url}/v1/connectors/http/ingress"))
        .bearer_auth("http-secret")
        .json(&json!({
            "session_id": "connector-session-policy",
            "content": "hello from ingress",
            "idempotency_key": "req-1"
        }))
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    assert_eq!(
        restored_run.run_id, first_run.run_id,
        "persisted connector ingress receipts should survive daemon restart"
    );
    let requests = wait_for_captured_requests(&captured_requests, 1).await?;
    assert_eq!(
        requests.len(),
        1,
        "persisted connector ingress receipts should prevent re-running the provider request after restart"
    );

    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn http_hmac_idempotency_and_receipt_fingerprint_survive_restart_on_a_real_daemon()
-> Result<()> {
    let bin = cli_bin()?;
    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let provider_base_url =
        spawn_openai_raw_mock_server(OPENAI_OK_RESPONSE, captured_requests.clone()).await?;

    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let routes_path = default_routes_path()?;
    let master_key = "0123456789abcdef0123456789abcdef";
    seed_default_route_auth_slots(&bin, &state_root, master_key)?;
    seed_generic_auth_slot(&bin, &state_root, master_key, "http.hmac", "hmac-secret")?;
    let openai_base_url = format!("{provider_base_url}/v1/responses");

    let (base_url, mut daemon) = start_daemon_ready_with_env(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        &routes_path,
        Some("openai"),
        [
            (AUTH_STORE_MASTER_KEY_ENV, master_key),
            ("OPENAI_BASE_URL", openai_base_url.as_str()),
        ],
    )?;

    let _: ConnectorView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("connectors"),
            OsString::from("put-http"),
            OsString::from("signed"),
            OsString::from("--json"),
            OsString::from(
                json!({
                    "hmac_secret": { "secret_ref": "http.hmac" },
                    "require_hmac_signature": true,
                    "fixed_session_id": "signed-http-demo",
                    "session_policy": { "create_if_missing": true }
                })
                .to_string(),
            ),
        ],
    )?;

    let client = Client::new();
    let path = "/v1/connectors/http/signed";
    let first_body = r#"{"content":"signed hello","idempotency_key":"req-1"}"#;
    let (timestamp, signature) = signed_http_connector_headers(path, first_body, "hmac-secret");
    let first_run = client
        .post(format!("{base_url}{path}"))
        .header("x-kheish-timestamp", timestamp)
        .header("x-kheish-signature", signature)
        .header(header::CONTENT_TYPE, "application/json")
        .body(first_body.to_string())
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    let _: RunView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("runs"),
            OsString::from("wait"),
            OsString::from(first_run.run_id.clone()),
        ],
    )?;
    assert_eq!(
        wait_for_captured_requests(&captured_requests, 1)
            .await?
            .len(),
        1
    );

    let shard_path =
        resolve_storage_path_for_read(&state_root.join("connector-ingress/http"), "signed", "json");
    let shard = fs::read_to_string(&shard_path)
        .with_context(|| format!("failed to read {}", shard_path.display()))?;
    assert!(shard.contains("\"fingerprint\""), "{shard}");
    assert!(!shard.contains("req-1"), "{shard}");

    let (timestamp, signature) = signed_http_connector_headers(path, first_body, "hmac-secret");
    let duplicate = client
        .post(format!("{base_url}{path}"))
        .header("x-kheish-timestamp", timestamp)
        .header("x-kheish-signature", signature)
        .header(header::CONTENT_TYPE, "application/json")
        .body(first_body.to_string())
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    assert_eq!(duplicate.run_id, first_run.run_id);

    let conflict_body = r#"{"content":"different","idempotency_key":"req-1"}"#;
    let (timestamp, signature) = signed_http_connector_headers(path, conflict_body, "hmac-secret");
    let conflict = client
        .post(format!("{base_url}{path}"))
        .header("x-kheish-timestamp", timestamp)
        .header("x-kheish-signature", signature)
        .header(header::CONTENT_TYPE, "application/json")
        .body(conflict_body.to_string())
        .send()
        .await?;
    assert_eq!(conflict.status(), StatusCode::CONFLICT);
    assert!(
        conflict.text().await?.contains("different payload"),
        "same idempotency key with a different payload should conflict"
    );

    stop_daemon(&mut daemon)?;
    let (base_url, mut daemon) = start_daemon_ready_with_env(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        &routes_path,
        Some("openai"),
        [
            (AUTH_STORE_MASTER_KEY_ENV, master_key),
            ("OPENAI_BASE_URL", openai_base_url.as_str()),
        ],
    )?;

    let (timestamp, signature) = signed_http_connector_headers(path, first_body, "hmac-secret");
    let restored = client
        .post(format!("{base_url}{path}"))
        .header("x-kheish-timestamp", timestamp)
        .header("x-kheish-signature", signature)
        .header(header::CONTENT_TYPE, "application/json")
        .body(first_body.to_string())
        .send()
        .await?
        .error_for_status()?
        .json::<RunView>()
        .await?;
    assert_eq!(restored.run_id, first_run.run_id);
    assert_eq!(
        wait_for_captured_requests(&captured_requests, 1)
            .await?
            .len(),
        1,
        "restored HMAC idempotency receipt should not re-run the provider"
    );

    let (timestamp, signature) = signed_http_connector_headers(path, conflict_body, "hmac-secret");
    let restored_conflict = client
        .post(format!("{base_url}{path}"))
        .header("x-kheish-timestamp", timestamp)
        .header("x-kheish-signature", signature)
        .header(header::CONTENT_TYPE, "application/json")
        .body(conflict_body.to_string())
        .send()
        .await?;
    assert_eq!(restored_conflict.status(), StatusCode::CONFLICT);

    let revoke_hmac: Value = run_cli_json(
        &bin,
        &base_url,
        ["runtime", "auth", "revoke-slot", "http.hmac"],
    )?;
    assert_eq!(
        revoke_hmac.get("slot_id").and_then(Value::as_str),
        Some("http.hmac")
    );
    let (timestamp, signature) = signed_http_connector_headers(path, first_body, "hmac-secret");
    let revoked = client
        .post(format!("{base_url}{path}"))
        .header("x-kheish-timestamp", timestamp)
        .header("x-kheish-signature", signature)
        .header(header::CONTENT_TYPE, "application/json")
        .body(first_body.to_string())
        .send()
        .await?;
    assert_eq!(
        revoked.status(),
        StatusCode::NOT_FOUND,
        "HMAC secret revoke should remove the HTTP connector from the live registry"
    );

    stop_daemon(&mut daemon)?;
    let (base_url, _daemon) = start_daemon_ready_with_env(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        &routes_path,
        Some("openai"),
        [
            (AUTH_STORE_MASTER_KEY_ENV, master_key),
            ("OPENAI_BASE_URL", openai_base_url.as_str()),
        ],
    )?;
    let (timestamp, signature) = signed_http_connector_headers(path, first_body, "hmac-secret");
    let revoked_after_restart = client
        .post(format!("{base_url}{path}"))
        .header("x-kheish-timestamp", timestamp)
        .header("x-kheish-signature", signature)
        .header(header::CONTENT_TYPE, "application/json")
        .body(first_body.to_string())
        .send()
        .await?;
    assert_eq!(
        revoked_after_restart.status(),
        StatusCode::NOT_FOUND,
        "HMAC secret revoke should persistently remove the daemon-managed HTTP connector"
    );

    Ok(())
}

