#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn webhook_sidecar_loads_credential_slots_on_a_real_daemon() -> Result<()> {
    let bin = cli_bin()?;
    let launcher = python_connector_script()?;
    let temp = TempDir::new()?;
    let state_root = temp.path().join("state");
    let workspace_root = temp.path().join("workspace");
    fs::create_dir_all(&state_root)?;
    fs::create_dir_all(&workspace_root)?;
    let routes_path = default_routes_path()?;
    let master_key = "0123456789abcdef0123456789abcdef";
    seed_default_route_auth_slots(&bin, &state_root, master_key)?;

    let captured_requests = Arc::new(Mutex::new(Vec::new()));
    let openai_base_url =
        spawn_openai_raw_mock_server(OPENAI_OK_RESPONSE, captured_requests.clone()).await?;
    let (base_url, _daemon) = start_daemon_ready_with_env(
        &bin,
        &temp,
        &state_root,
        &workspace_root,
        &routes_path,
        Some("openai"),
        [
            (AUTH_STORE_MASTER_KEY_ENV, master_key),
            ("OPENAI_BASE_URL", openai_base_url.as_str()),
        ],
    )?;

    let client = Client::new();
    let routes_json = json!({
        "demo": {
            "secret": "hook-secret",
            "prompt_template": "Webhook payload:\n{payload_json}",
            "session_mode": "per_delivery"
        }
    });
    let secret_write = client
        .post(format!("{base_url}/v1/runtime/secrets"))
        .json(&json!({
            "slot_id": "sidecars.webhook.routes",
            "provider": "generic",
            "mode": "opaque_secret",
            "state": { "value": routes_json.to_string() },
            "updated_at_ms": Utc::now().timestamp_millis(),
        }))
        .send()
        .await?;
    assert_eq!(secret_write.status(), StatusCode::OK);

    let bind = reserve_bind_address()?;
    let capture_path = temp.path().join("webhook-credential-deliveries.jsonl");
    let connector_payload = json!({
        "platform": "webhook",
        "mode": "child_process",
        "base_url": format!("http://{bind}"),
        "shared_token": { "value": "webhook-secret" },
        "include_self_output": true,
        "session_policy": { "create_if_missing": true },
        "child_process": {
            "command": "python3",
            "args": [launcher.to_string_lossy().to_string(), "webhook"],
            "env": {
                "KHEISH_EXTERNAL_CONNECTOR_DELIVERY_CAPTURE_PATH": capture_path.to_string_lossy().to_string()
            },
            "credential_slots": {
                "WEBHOOK_ROUTES_JSON": "sidecars.webhook.routes"
            }
        }
    });
    let _: ConnectorView = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("connectors"),
            OsString::from("put-external"),
            OsString::from("webhook-credential-sidecar"),
            OsString::from("--json"),
            OsString::from(connector_payload.to_string()),
        ],
    )?;
    wait_for_external_sidecar_health(&format!("http://{bind}"), "webhook-secret").await?;

    let body = json!({"event_type": "push", "title": "hello from credential slot"}).to_string();
    let mut mac = Hmac::<Sha256>::new_from_slice(b"hook-secret")?;
    mac.update(body.as_bytes());
    let signature = format!("sha256={}", hex::encode(mac.finalize().into_bytes()));
    let response = client
        .post(format!("http://{bind}/webhooks/demo"))
        .header(header::CONTENT_TYPE, "application/json")
        .header("X-Hub-Signature-256", signature)
        .header("X-GitHub-Delivery", "credential-delivery-1")
        .body(body)
        .send()
        .await?;
    assert!(response.status().is_success());
    let deliveries = wait_for_jsonl_records(&capture_path, 1).await?;
    assert_eq!(
        deliveries[0].get("content").and_then(Value::as_str),
        Some("ok")
    );
    assert_eq!(
        wait_for_captured_requests(&captured_requests, 1)
            .await?
            .len(),
        1
    );

    let subject_before_revoke: AuthSubjectStatus = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("runtime"),
            OsString::from("auth"),
            OsString::from("subject"),
            OsString::from("connector:webhook-credential-sidecar"),
        ],
    )?;
    assert_eq!(subject_before_revoke.active_connector_lease_ids.len(), 1);
    let lease_id = subject_before_revoke.active_connector_lease_ids[0].clone();
    let revoke_slot: Value = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("runtime"),
            OsString::from("auth"),
            OsString::from("revoke-slot"),
            OsString::from("sidecars.webhook.routes"),
        ],
    )?;
    assert_eq!(
        revoke_slot.get("slot_id").and_then(Value::as_str),
        Some("sidecars.webhook.routes")
    );
    assert!(
        revoke_slot
            .get("revoked_leases")
            .and_then(Value::as_u64)
            .is_some_and(|count| count >= 1),
        "expected revoke-slot to revoke the active connector lease: {revoke_slot}"
    );
    let lease_after_revoke: CredentialLeaseStatus = run_cli_json(
        &bin,
        &base_url,
        vec![
            OsString::from("runtime"),
            OsString::from("auth"),
            OsString::from("lease"),
            OsString::from(lease_id),
        ],
    )?;
    assert!(lease_after_revoke.revoked);
    assert!(!lease_after_revoke.active);
    let lease_json = serde_json::to_value(&lease_after_revoke)?;
    assert!(
        lease_json.pointer("/lease/token_digest").is_none(),
        "operator lease view must not expose token_digest: {lease_json}"
    );
    let stopped_deadline = tokio::time::Instant::now() + Duration::from_secs(10);
    loop {
        match client
            .get(format!("http://{bind}/health"))
            .bearer_auth("webhook-secret")
            .send()
            .await
        {
            Ok(response) if response.status().is_success() => {}
            _ => break,
        }
        if tokio::time::Instant::now() >= stopped_deadline {
            bail!("credential-backed sidecar stayed healthy after slot revoke");
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
    Ok(())
}

